BOOK_DATA = [{'page_no': 1, 'title': "Jonathan Harker's Journey to Transylvania", 'tr_title': "Jonathan Harker'ın Transilvanya Yolculuğu", 'vocab_focus': [('solicitor', 'hukuk danışmanı, avukat'), ('estate', 'mülk, arazi'), ('superstition', 'batıl inanç'), ('crucifix', 'haç'), ('pass', 'dağ geçidi'), ('carriage', 'at arabası, fayton'), ('howling', 'uluma, uğultu'), ('inhospitable', 'misafirperver olmayan, çetin')], 'sentences': [{'id': 1, 'text': 'Jonathan Harker, a young English solicitor, was traveling across Eastern Europe on an important business assignment.', 'translation': 'Genç bir İngiliz avukat olan Jonathan Harker, önemli bir iş göreviyle Doğu Avrupa boyunca seyahat ediyordu.', 'notes': 'business assignment: iş görevi.'}, {'id': 2, 'text': 'His employer had sent him to Transylvania to finalize the purchase of an English estate for a wealthy nobleman.', 'translation': "İşvereni, varlıklı bir asilzade adına bir İngiliz mülkünün satın alımını tamamlamak üzere onu Transilvanya'ya göndermişti.", 'notes': 'finalize purchase: satın alımı tamamlamak.'}, {'id': 3, 'text': 'This mysterious nobleman was known throughout the remote Carpathian mountains as Count Dracula.', 'translation': 'Bu gizemli soylu, ücra Karpat dağları boyunca Kont Drakula olarak biliniyordu.', 'notes': 'remote mountains: ücra dağlar.'}, {'id': 4, 'text': 'Jonathan reached the frontier town of Bistritz and took a room at the Golden Krone Hotel.', 'translation': "Jonathan sınır kasabası Bistritz'e ulaştı ve Golden Krone Oteli'nde bir oda tuttu.", 'notes': 'frontier town: sınır kasabası.'}, {'id': 5, 'text': 'The landlord handed him a handwritten letter from Count Dracula welcoming him warmly to the region.', 'translation': "Otel sahibi, ona Kont Drakula'dan gelen ve bölgeye sıcak bir hoş geldin dileyen el yazısı bir mektup verdi.", 'notes': 'handwritten letter: el yazısı mektup.'}, {'id': 6, 'text': 'However, when Jonathan mentioned his destination, the landlord and his wife grew pale with terror.', 'translation': 'Ancak Jonathan gideceği yeri söylediğinde, otel sahibi ve eşinin yüzü dehşetle sarardı.', 'notes': 'grew pale with terror: dehşetle rengi soldu.'}, {'id': 7, 'text': '"Must you really go there, young master?" the trembling innkeeper\'s wife asked in broken German.', 'translation': '"Oraya gerçekten gitmek zorunda mısınız genç beyim?" diye sordu titreyen hancının karısı kırık bir Almancayla.', 'notes': 'broken German: kırık bir Almanca.'}, {'id': 8, 'text': '"Do you not know that tonight is the Eve of Saint George, when evil spirits walk freely upon the earth?"', 'translation': '"Bu gecenin, kötü ruhların yeryüzünde serbestçe dolaştığı Aziz George Arifesi olduğunu bilmiyor musunuz?"', 'notes': 'evil spirits: kötü ruhlar.'}, {'id': 9, 'text': 'She took a rosary with a crucifix from her own neck and pleaded with Jonathan to wear it for protection.', 'translation': "Kendi boynundan haçlı bir tespih çıkardı ve korunması için takması konusunda Jonathan'a yalvardı.", 'notes': 'pleaded for protection: korunma için yalvardı.'}, {'id': 10, 'text': 'Though Jonathan was an educated churchman who did not believe in superstitions, he accepted the crucifix politely.', 'translation': 'Batıl inançlara inanmayan eğitimli bir din mensubu olmasına rağmen Jonathan, haçı kibarca kabul etti.', 'notes': 'did not believe in superstitions: batıl inançlara inanmazdı.'}, {'id': 11, 'text': 'The next morning, he boarded the crowded public diligence departing for the rugged Borgo Pass.', 'translation': "Ertesi sabah, sarp Borgo Geçidi'ne doğru hareket eden kalabalık posta arabasına bindi.", 'notes': 'public diligence: kamu posta arabası.'}, {'id': 12, 'text': 'The passengers in the carriage whispered among themselves, glancing at Jonathan with expressions of mournful pity.', 'translation': "Faytondaki yolcular kendi aralarında fısıldaşıyor, Jonathan'a hüzünlü bir acıma ifadesiyle bakıyorlardı.", 'notes': 'mournful pity: hüzünlü acıma.'}, {'id': 13, 'text': 'Whenever the carriage passed roadside shrines, peasants knelt in the mud and made the sign of the cross.', 'translation': 'Araba yol kenarındaki türbelerin yanından her geçtiğinde köylüler çamurda diz çöküp istavroz çıkarıyorlardı.', 'notes': 'sign of the cross: haç çıkarma, istavroz.'}, {'id': 14, 'text': 'The road climbed steadily through magnificent pine forests and dark, gloomy mountain gorges.', 'translation': 'Yol muhteşem çam ormanlarının ve karanlık, kasvetli dağ kanyonlarının arasından durmaksızın yükseliyordu.', 'notes': 'gloomy gorges: kasvetli kanyonlar.'}, {'id': 15, 'text': 'As the sun set behind the jagged peaks, darkness fell swiftly across the inhospitable landscape.', 'translation': 'Güneş sarp zirvelerin ardında batarken bu çetin coğrafyanın üzerine karanlık hızla çöktü.', 'notes': 'jagged peaks: sarp zirveler.'}, {'id': 16, 'text': 'At the summit of the pass, the public carriage halted in the freezing mountain mist.', 'translation': 'Geçidin zirvesinde posta arabası dondurucu dağ sisinin içinde durdu.', 'notes': 'summit of the pass: geçidin zirvesi.'}, {'id': 17, 'text': 'Suddenly, a private calèche drawn by four black horses emerged silently from the gloomy shadows.', 'translation': 'Ansızın, dört siyah atın çektiği özel bir fayton kasvetli gölgelerin arasından sessizce süzüldü.', 'notes': 'emerged silently: sessizce belirdi.'}, {'id': 18, 'text': 'The driver was a tall man whose face was completely hidden beneath a heavy black cloak and broad hat.', 'translation': 'Sürücü, yüzü kalın siyah bir pelerinin ve geniş şapkanın altına tamamen gizlenmiş uzun boylu bir adamdı.', 'notes': 'heavy black cloak: kalın siyah pelerin.'}, {'id': 19, 'text': '"The Englishman is expected; take your place beside me," the driver commanded in a harsh, cold voice.', 'translation': '"İngiliz bekleniyor; yanımda yerini al," diye sert ve soğuk bir sesle buyurdu sürücü.', 'notes': 'harsh cold voice: sert soğuk ses.'}, {'id': 20, 'text': 'As Jonathan climbed into the calèche, the distant howling of wolves echoed ominously across the frozen valleys.', 'translation': 'Jonathan faytona binerken, kurtların uzaktan gelen uğursuz ulumaları donmuş vadilerde yankılandı.', 'notes': 'echoed ominously: uğursuzca yankılandı.'}]}, {'page_no': 2, 'title': 'Midnight Arrival at Castle Dracula', 'tr_title': "Drakula Şatosu'na Gece Yarısı Varış", 'vocab_focus': [('calèche', 'hafif fayton'), ('cloak', 'pelerin'), ('flame', 'alev, ateş'), ('courtyard', 'avlu'), ('massive', 'muazzam, devasa'), ('aquiline', 'kartal gagası gibi kemerli'), ('hospitality', 'misafirperverlik'), ('shadow', 'gölge')], 'sentences': [{'id': 21, 'text': 'The black horses raced at reckless speed through the winding, snow-covered mountain roads.', 'translation': 'Siyah atlar kıvrımlı, karla kaplı dağ yollarında baş döndürücü bir hızla koşuyordu.', 'notes': 'reckless speed: pervasız/çılgınca hız.'}, {'id': 22, 'text': 'More than once, Jonathan saw strange blue flames flickering mysteriously in the roadside darkness.', 'translation': 'Jonathan bir kereden fazla yol kenarındaki karanlıkta esrarengizce parıldayan tuhaf mavi alevler gördü.', 'notes': 'blue flames flickering: titrek mavi alevler.'}, {'id': 23, 'text': 'Whenever a flame appeared, the mysterious driver leaped down to mark the exact spot with stones.', 'translation': 'Her alev belirişinde o gizemli sürücü arabadan atlayıp yeri taşlarla tam olarak işaretliyordu.', 'notes': 'mark exact spot: tam noktayı işaretlemek.'}, {'id': 24, 'text': 'Presently, dozens of ferocious wolves gathered along the roadway, their eyes gleaming like red coals.', 'translation': 'Çok geçmeden onlarca vahşi kurt yol boyunca toplandı; gözleri kor gibi kızıl parıldıyordu.', 'notes': 'gleaming like red coals: kor gibi parlayan.'}, {'id': 25, 'text': 'Jonathan gripped his seat in terror as the hungry pack closed in around the moving carriage.', 'translation': 'Aç sürü hareket eden arabanın etrafını sararken Jonathan dehşet içinde koltuğunu kavradı.', 'notes': 'gripped in terror: dehşetle kavradı.'}, {'id': 26, 'text': 'The driver stood upright, raised his hand with an authoritative gesture, and commanded the wolves to disperse.', 'translation': 'Sürücü ayağa kalktı, buyurgan bir hareketle elini kaldırdı ve kurtlara dağılmalarını emretti.', 'notes': 'authoritative gesture: buyurgan/otoriter bir el hareketi.'}, {'id': 27, 'text': "To Jonathan's astonishment, the savage beasts slunk silently away into the dark shadows of the forest.", 'translation': "Jonathan'ın şaşkın bakışları arasında vahşi canavarlar ormanın karanlık gölgelerine doğru sessizce sıvıştılar.", 'notes': 'slunk away: sıvıştı, gizlice uzaklaştı.'}, {'id': 28, 'text': 'At midnight, the carriage passed through a massive stone gateway into the courtyard of a vast castle.', 'translation': 'Gece yarısı araba muazzam bir taş kapıdan geçerek devasa bir kalenin avlusuna girdi.', 'notes': 'stone gateway: taş kapı kemeri.'}, {'id': 29, 'text': 'The great building was dark, gloomy, and ruined, with tall battlements silhouetted against the moonlight.', 'translation': 'Büyük bina karanlık, kasvetli ve haraptı; yüksek burçları ay ışığına karşı siluet oluşturuyordu.', 'notes': 'tall battlements: yüksek burçlar/siperler.'}, {'id': 30, 'text': 'Not a single light shone from the narrow gothic windows, and not a single servant came forth to meet him.', 'translation': 'Dar gotik pencerelerden tek bir ışık sızmıyordu ve onu karşılamak için tek bir uşak bile öne çıkmadı.', 'notes': 'narrow gothic windows: dar gotik pencereler.'}, {'id': 31, 'text': 'The mysterious driver vanished into the darkness, leaving Jonathan standing alone on the cobblestones.', 'translation': "O gizemli sürücü Jonathan'ı arnavut kaldırımı taşların üzerinde tek başına bırakarak karanlıkta kayboldu.", 'notes': 'cobblestones: arnavut kaldırımı taşları.'}, {'id': 32, 'text': 'Jonathan approached the heavy oak door studded with iron nails and hesitated, unsure whether to knock.', 'translation': 'Jonathan demir çivilerle perçinlenmiş ağır meşe kapıya yaklaştı ve kapıyı çalıp çalmama konusunda tereddüt etti.', 'notes': 'studded with iron nails: demir çivilerle perçinli.'}, {'id': 33, 'text': 'Before his hand could touch the wood, heavy bolts slid back with a loud clatter and the door swung open.', 'translation': 'Eli tahtaya değmeden önce ağır sürgüler yüksek bir şakırtıyla geriye çekildi ve kapı ardına kadar açıldı.', 'notes': 'bolts slid back: sürgüler geri çekildi.'}, {'id': 34, 'text': 'Before him stood a tall old man, clean-shaven except for a long white mustache, dressed entirely in black.', 'translation': 'Karşısında, uzun beyaz bir bıyık haricinde sinekkaydı tıraşlı ve baştan aşağı siyahlara bürünmüş uzun boylu yaşlı bir adam duruyordu.', 'notes': 'clean-shaven: sinekkaydı tıraşlı.'}, {'id': 35, 'text': 'He held a flickering silver lamp, whose light cast dancing shadows against the ancient masonry.', 'translation': 'Işığı kadim taş duvarlara dans eden gölgeler vuran titrek gümüş bir lamba tutuyordu.', 'notes': 'flickering silver lamp: titrek gümüş lamba.'}, {'id': 36, 'text': '"Welcome to my house; enter freely and of your own will!" the old man exclaimed in flawless English.', 'translation': '"Evime hoş geldiniz; serbestçe ve kendi rızanızla giriniz!" diye seslendi yaşlı adam kusursuz bir İngilizceyle.', 'notes': 'enter of your own will: kendi iradenizle giriniz.'}, {'id': 37, 'text': "As the host grasped Jonathan's hand, Jonathan could not help but shudder at the touch.", 'translation': "Ev sahibi Jonathan'ın elini kavradığında Jonathan bu temas karşısında irkilmekten kendini alamadı.", 'notes': 'could not help but shudder: irkilmekten kendini alamadı.'}, {'id': 38, 'text': "The man's fingers felt like ice, resembling the cold grip of a corpse rather than living flesh.", 'translation': 'Adamın parmakları buz gibiydi; yaşayan bir candan ziyade bir cesedin soğuk kavramasını andırıyordu.', 'notes': 'cold grip of a corpse: bir cesedin soğuk tutuşu.'}, {'id': 39, 'text': '"I am Count Dracula," the nobleman said, bowing with courtly elegance; "pray step inside, Mr. Harker."', 'translation': '"Ben Kont Drakula," dedi soylu saray zarafetiyle eğilerek; "lütfen içeri buyurunuz Bay Harker."', 'notes': 'courtly elegance: saray zarafeti.'}, {'id': 40, 'text': 'He led Jonathan into a warm, comfortable sitting room where a roaring fire blazed in the stone hearth.', 'translation': "Jonathan'ı taş şöminesinde gürül gürül bir ateşin yandığı sıcak ve konforlu bir oturma odasına götürdü.", 'notes': 'roaring fire: gürül gürül yanan ateş.'}]}, {'page_no': 3, 'title': 'Life in the Castle and the Mirror', 'tr_title': 'Şatodaki Yaşam ve Aynasız Duvarlar', 'vocab_focus': [('roast', 'kızartma'), ('library', 'kütüphane'), ('reflection', 'yansıma'), ('shaving', 'tıraş olma'), ('beast', 'canavar, vahşi hayvan'), ('instinct', 'içgüdü'), ('aristocracy', 'soylular, aristokrasi'), ('deed', 'tapu, mülk senedi')], 'sentences': [{'id': 41, 'text': 'A lavish supper of roast chicken, cheese, and spiced wine was waiting upon a mahogany table.', 'translation': 'Maun bir masanın üzerinde kızarmış tavuk, peynir ve baharatlı şaraptan oluşan mükellef bir akşam yemeği bekliyordu.', 'notes': 'lavish supper: mükellef akşam yemeği.'}, {'id': 42, 'text': 'The Count invited Jonathan to eat, but apologized that he himself had already dined and would take nothing.', 'translation': "Kont Jonathan'ı yemeye davet etti ancak kendisinin daha önce akşam yemeği yediğini ve bir şey almayacağını belirterek özür diledi.", 'notes': 'had already dined: çoktan yemek yemişti.'}, {'id': 43, 'text': "While Jonathan ate, he studied his host's striking and aristocratic countenance with growing interest.", 'translation': 'Jonathan yemeğini yerken ev sahibinin çarpıcı ve aristokratik yüz hatlarını artan bir ilgiyle inceledi.', 'notes': 'aristocratic countenance: soylu yüz hatları/çehre.'}, {'id': 44, 'text': "The Count's face was extremely pale, his nose thin and aquiline, and his eyebrows remarkably bushy.", 'translation': "Kont'un yüzü aşırı derecede solgundu, burnu ince ve kemerliydi, kaşları ise son derece gürdü.", 'notes': 'remarkably bushy: dikkat çekici derecede gür.'}, {'id': 45, 'text': 'His mouth revealed unusually sharp white teeth that protruded noticeably over his vivid red lips.', 'translation': 'Ağzı, canlı kırmızı dudaklarının üzerinden belirgin şekilde taşan olağandışı sivri beyaz dişleri gözler önüne seriyordu.', 'notes': 'sharp white teeth: sivri beyaz dişler.'}, {'id': 46, 'text': "Furthermore, Jonathan noticed with unease that hairs grew from the very centers of the Count's pale palms.", 'translation': "Üstelik Jonathan Kont'un solgun avuçlarının tam ortasından kıllar bittiğini huzursuzlukla fark etti.", 'notes': 'centers of pale palms: soluk avuçların ortası.'}, {'id': 47, 'text': 'They spent hours in the library discussing the Carfax estate that the Count had purchased near Purfleet, England.', 'translation': "Kont'un İngiltere'de Purfleet yakınlarında satın aldığı Carfax mülkünü tartışarak kütüphanede saatler geçirdiler.", 'notes': 'library: kütüphane.'}, {'id': 48, 'text': '"I am eager to walk the crowded streets of London and share the life of your great metropolis," Dracula mused.', 'translation': '"Londra\'nın kalabalık caddelerinde yürümeyi ve büyük metropolünüzün hayatını paylaşmayı sabırsızlıkla bekliyorum," dedi Drakula düşünceli bir edayla.', 'notes': 'great metropolis: büyük metropol.'}, {'id': 49, 'text': 'Day after day passed, and Jonathan observed that he never saw Dracula during daylight hours.', 'translation': "Günler birbirini kovaladı ve Jonathan gün ışığı saatlerinde Drakula'yı hiçbir zaman görmediğini gözlemledi.", 'notes': 'daylight hours: gün ışığı saatleri.'}, {'id': 50, 'text': 'The Count appeared only after dusk, conversing for hours before vanishing before the first light of dawn.', 'translation': 'Kont sadece alacakaranlıktan sonra ortaya çıkıyor, şafağın ilk ışıklarından önce kaybolmadan evvel saatlerce sohbet ediyordu.', 'notes': 'after dusk: alacakaranlıktan sonra.'}, {'id': 51, 'text': 'Jonathan also realized with surprise that there was not a single mirror in the entire castle.', 'translation': 'Jonathan ayrıca bütün şatoda tek bir aynanın bile bulunmadığını şaşkınlıkla fark etti.', 'notes': 'not a single mirror: tek bir ayna bile yok.'}, {'id': 52, 'text': 'One morning, Jonathan hung his own small shaving glass near the window of his bedchamber.', 'translation': 'Bir sabah Jonathan kendi küçük tıraş aynasını yatak odasının penceresinin yanına astı.', 'notes': 'shaving glass: tıraş aynası.'}, {'id': 53, 'text': 'While shaving his chin, he suddenly felt a hand touch his shoulder and heard Dracula speak behind him.', 'translation': "Çenesini tıraş ederken ansızın bir elin omzuna dokunduğunu hissetti ve arkasından Drakula'nın konuştuğunu duydu.", 'notes': 'shaving his chin: çenesini tıraş ederken.'}, {'id': 54, 'text': '"Good morning, my friend," the Count said softly in his ear.', 'translation': '"Günaydın dostum," dedi Kont kulağına usulca.', 'notes': 'said softly: usulca söyledi.'}, {'id': 55, 'text': "Jonathan looked into the mirror, expecting to see the Count's reflection standing right behind his shoulder.", 'translation': "Jonathan hemen omzunun arkasında duran Kont'un yansımasını görmeyi bekleyerek aynaya baktı.", 'notes': 'expecting to see: görmeyi bekleyerek.'}, {'id': 56, 'text': 'To his profound horror, the glass reflected the entire room behind him, but Count Dracula had no reflection whatsoever!', 'translation': "Büyük bir dehşetle gördü ki ayna arkasındaki bütün odayı yansıtıyordu fakat Kont Drakula'nın hiçbir yansıması yoktu!", 'notes': 'no reflection whatsoever: en ufak bir yansıması bile yok.'}, {'id': 57, 'text': "Startled by the discovery, Jonathan's hand slipped, and the sharp razor nicked the skin of his throat.", 'translation': "Bu keşifle irkilen Jonathan'ın eli kaydı ve keskin ustura boğazındaki deriyi kesti.", 'notes': 'sharp razor: keskin ustura.'}, {'id': 58, 'text': 'A tiny bead of red blood trickled down his neck, glistening in the morning sunlight.', 'translation': 'Sabah güneşinde parıldayan küçücük bir kırmızı kan damlası boynundan aşağı süzüldü.', 'notes': 'tiny bead of blood: küçücük kan damlası.'}, {'id': 59, 'text': "The Count's eyes blazed with sudden, demonic hunger, and his hands lunged forward violently toward Jonathan's throat.", 'translation': "Kont'un gözleri ani, şeytani bir açlıkla alevlendi ve elleri şiddetle Jonathan'ın boğazına doğru atıldı.", 'notes': 'demonic hunger: şeytani açlık.'}, {'id': 60, 'text': "Yet when his cold fingers brushed against the crucifix hanging from Jonathan's neck, Dracula recoiled as if burned.", 'translation': "Fakat soğuk parmakları Jonathan'ın boynunda asılı duran haça değer değmez, Drakula sanki yanmış gibi geriye irkildi.", 'notes': 'recoiled as if burned: yanmış gibi geri çekildi.'}]}, {'page_no': 4, 'title': 'A Prisoner in the Abyss', 'tr_title': 'Uçurumdaki Mahkûm', 'vocab_focus': [('prisoner', 'tutsak, mahkûm'), ('precipice', 'uçurum'), ('lizard', 'kertenkele'), ('chasm', 'derin yarık, uçurum'), ('masonry', 'taş işçiliği, duvar'), ('dread', 'dehşet, yılgı'), ('lock', 'kilit'), ('despair', 'umutsuzluk, çaresizlik')], 'sentences': [{'id': 61, 'text': '"Take care," the Count warned with a sinister snarl; "it is a wretched thing to cut yourself in this country."', 'translation': '"Dikkatli ol," diye uyardı Kont sinsi bir hırıltıyla; "bu ülkede kendini kesmek talihsiz bir şeydir."', 'notes': 'sinister snarl: meşum/sinsi bir hırıltı.'}, {'id': 62, 'text': 'Snatching the shaving mirror, Dracula cast it out the high window, where it shattered upon the stones below.', 'translation': 'Tıraş aynasını kapan Drakula onu yüksek pencereden fırlattı ve ayna aşağıdaki kayalıkların üzerinde tuzla buz oldu.', 'notes': 'shattered upon the stones: taşların üzerinde parçalandı.'}, {'id': 63, 'text': 'The Count departed without another word, leaving Jonathan alone to bandage his minor wound.', 'translation': "Kont tek kelime daha etmeden ayrıldı ve Jonathan'ı küçük yarasını sarması için yalnız bıraktı.", 'notes': 'minor wound: küçük yara.'}, {'id': 64, 'text': 'Growing increasingly suspicious, Jonathan decided to thoroughly examine every corridor and exit of the castle.', 'translation': 'Giderek daha fazla şüphelenen Jonathan, şatonun her koridorunu ve çıkışını etraflıca incelemeye karar verdi.', 'notes': 'thoroughly examine: etraflıca incelemek.'}, {'id': 65, 'text': 'He walked through grand galleries, winding staircases, and silent halls adorned with faded tapestries.', 'translation': 'Görkemli galerilerden, döner merdivenlerden ve solmuş duvar halılarıyla süslü sessiz salonlardan geçti.', 'notes': 'faded tapestries: solmuş duvar halıları.'}, {'id': 66, 'text': 'To his dismay, every heavy oak door leading outside was securely locked and bolted from within.', 'translation': 'Onu kahreden bir şekilde, dışarıya açılan her ağır meşe kapı sağlam bir şekilde kilitlenmiş ve içeriden sürgülenmişti.', 'notes': 'to his dismay: onu kahreden bir şekilde.'}, {'id': 67, 'text': 'The dreadful truth rushed upon his mind with overwhelming weight: he was not a guest, but a helpless prisoner!', 'translation': 'O korkunç gerçek ezici bir ağırlıkla zihnine üşüştü: O bir misafir değil, çaresiz bir tutsaktı!', 'notes': 'overwhelming weight: ezici ağırlık.'}, {'id': 68, 'text': 'The only windows that could be opened looked out over a dizzying, thousand-foot stone precipice.', 'translation': 'Açılabilen yegane pencereler, bin fitlik baş döndürücü bir taş uçuruma bakıyordu.', 'notes': 'dizzying precipice: baş döndürücü uçurum.'}, {'id': 69, 'text': 'Far down in the dark chasm, a wild mountain river rushed over sharp jagged boulders.', 'translation': 'Aşağıdaki karanlık yarığın ta dibinde, vahşi bir dağ nehri keskin sarp kayalıkların üzerinden akıyordu.', 'notes': 'jagged boulders: sivri sarp kayalar.'}, {'id': 70, 'text': 'One evening at twilight, Jonathan leaned out of his high window to breathe the cool mountain air.', 'translation': 'Bir akşam alacakaranlıkta Jonathan serin dağ havasını solumak için yüksek penceresinden dışarı sarktı.', 'notes': 'cool mountain air: serin dağ havası.'}, {'id': 71, 'text': 'Looking down the sheer stone wall, he saw something moving that chilled the very blood in his veins.', 'translation': 'Düz taş duvardan aşağıya baktığında, damarlarındaki kanı donduran bir şeyin hareket ettiğini gördü.', 'notes': 'chilled blood in veins: damarlarındaki kanı dondurdu.'}, {'id': 72, 'text': "Count Dracula's head emerged from a lower window, followed slowly by his shoulders and entire body.", 'translation': "Kont Drakula'nın başı alt kattaki bir pencereden dışarı çıktı; ardından yavaşça omuzları ve tüm bedeni belirdi.", 'notes': 'emerged slowly: yavaşça belirdi.'}, {'id': 73, 'text': 'Face down against the sheer vertical wall, the Count began crawling rapidly downward like a monstrous lizard.', 'translation': 'Yüzüstü o dik dikey duvara yapışan Kont, canavarımsı bir kertenkele gibi hızla aşağı doğru sürünmeye başladı.', 'notes': 'crawling like a lizard: kertenkele gibi sürünerek.'}, {'id': 74, 'text': 'His fingers found purchase on microscopic cracks in the masonry where no human being could possibly cling.', 'translation': 'Parmakları, hiçbir insanın tutunmasının mümkün olmadığı taş işçiliğindeki mikroskobik çatlaklara tutunuyordu.', 'notes': 'found purchase: tutunacak yer buldu.'}, {'id': 75, 'text': 'His billowing black cloak spread around him like the dark leather wings of a gigantic bat.', 'translation': 'Dalgalanan siyah pelerini, devasa bir yarasasının koyu kösele kanatları gibi etrafına yayılıyordu.', 'notes': 'billowing cloak: dalgalanan pelerin.'}, {'id': 76, 'text': 'Dracula vanished into a dark opening hundreds of feet below, leaving Jonathan trembling with revulsion.', 'translation': "Drakula yüzlerce fit aşağıdaki karanlık bir oyukta kayboldu ve Jonathan'ı tiksintiyle titrer halde bıraktı.", 'notes': 'trembling with revulsion: tiksintiyle titreyerek.'}, {'id': 77, 'text': '"What manner of creature is this that wears the shape of a man?" Jonathan recorded in his private journal.', 'translation': '"İnsan kılığına bürünmüş bu nasıl bir yaratıktır böyle?" diye yazdı Jonathan özel günlüğüne.', 'notes': 'wears shape of man: insan kılığına bürünmek.'}, {'id': 78, 'text': 'He realized that every door was locked against him, and every hope of conventional escape was impossible.', 'translation': 'Her kapının yüzüne kilitlendiğini ve sıradan bir kaçış umudunun imkânsız olduğunu anladı.', 'notes': 'conventional escape: alışılagelmiş/sıradan kaçış.'}, {'id': 79, 'text': 'He was marooned in a desolate stronghold surrounded by supernatural terrors and bloodthirsty wolves.', 'translation': 'Doğaüstü dehşetler ve kana susamış kurtlarla çevrili ıssız bir kalede mahsur kalmıştı.', 'notes': 'bloodthirsty wolves: kana susamış kurtlar.'}, {'id': 80, 'text': 'Determined to survive, Jonathan resolved to search for any secret passage that might lead to freedom.', 'translation': 'Hayatta kalmaya kararlı olan Jonathan, özgürlüğe çıkarabilecek herhangi bir gizli geçit aramaya karar verdi.', 'notes': 'lead to freedom: özgürlüğe götürmek.'}]}, {'page_no': 5, 'title': 'The Three Vampire Sisters', 'tr_title': 'Üç Vampir Kardeş', 'vocab_focus': [('forbidden', 'yasak, yasaklanmış'), ('chamber', 'oda, salon'), ('sensual', 'duyusal, şehvetli'), ('fangs', 'sivri dişler'), ('hypnotic', 'hipnotik, büyüleyici'), ('wrath', 'şiddetli gazap, öfke'), ('creature', 'yaratık'), ('bundle', 'kundak, çıkın')], 'sentences': [{'id': 81, 'text': 'Before leaving the castle, Dracula had warned Jonathan never to sleep in any room other than his own.', 'translation': "Kaleden ayrılmadan önce Drakula Jonathan'ı kendi odası dışında hiçbir odada asla uyumaması konusunda uyarmıştı.", 'notes': 'warned never to sleep: asla uyumaması konusunda uyardı.'}, {'id': 82, 'text': '"There are bad dreams for those who sleep unwisely in this ancient house," the Count had hissed solemnly.', 'translation': '"Bu kadim evde tedbirsizce uyuyanlar için kötü kâbuslar vardır," diye tıslamıştı Kont ciddiyetle.', 'notes': 'unwisely: tedbirsizce, akılsızca.'}, {'id': 83, 'text': 'Yet weary from tension and dread, Jonathan found a quiet, furnished chamber in the southern wing.', 'translation': 'Fakat gerginlik ve yılgıdan tükenen Jonathan, güney kanadında sessiz, döşeli bir oda buldu.', 'notes': 'weary from tension: gerginlikten yorulmuş.'}, {'id': 84, 'text': 'Lying upon an antique sofa, he felt a soft, pleasant drowsiness stealing over his heavy eyelids.', 'translation': 'Antika bir divanın üzerine uzanarak ağırlaşan göz kapaklarını saran tatlı, hoş bir rehavet hissetti.', 'notes': 'pleasant drowsiness: hoş bir rehavet/uyku hali.'}, {'id': 85, 'text': 'Suddenly, the moonlight shining through the window seemed to swirl and coalesce into three misty human shapes.', 'translation': 'Ansızın, pencereden süzülen ay ışığı girdap gibi dönüp üç buğulu insan siluetine dönüşür gibi oldu.', 'notes': 'coalesce into shapes: siluetlere dönüşmek/şekil almak.'}, {'id': 86, 'text': 'Before Jonathan stood three young women, exquisitely beautiful and dressed in shimmering white garments.', 'translation': "Jonathan'ın karşısında, olağanüstü güzel ve parıldayan beyaz giysiler giymiş üç genç kadın belirdi.", 'notes': 'exquisitely beautiful: fevkalade güzel.'}, {'id': 87, 'text': 'Two were dark with piercing black eyes, while the third was fair-haired with golden curls.', 'translation': 'İkisi delici kara gözleriyle esmerdi, üçüncüsü ise altın sarısı bukleleriyle sarışındı.', 'notes': 'piercing black eyes: delici kara gözler.'}, {'id': 88, 'text': 'They whispered together with silvery laughter that sounded like the tinkling of delicate glass bells.', 'translation': 'Narin cam çanların şıngırtısını andıran gümüşsü kahkahalarla kendi aralarında fısıldaştılar.', 'notes': 'silvery laughter: gümüşsü kahkaha.'}, {'id': 89, 'text': '"Go on! You are the first, and we shall follow!" the two dark women murmured softly.', 'translation': '"Hadi başla! İlk sen varsın, biz de ardından geleceğiz!" diye fısıldadı iki esmer kadın usulca.', 'notes': 'murmured softly: usulca mırıldandı.'}, {'id': 90, 'text': 'The fair woman approached the sofa, kneeling beside Jonathan with a seductive and hypnotic smile.', 'translation': "Sarışın kadın baştan çıkarıcı ve büyüleyici bir gülümsemeyle Jonathan'ın yanında diz çökerek divana yaklaştı.", 'notes': 'seductive smile: baştan çıkarıcı gülümseme.'}, {'id': 91, 'text': 'Jonathan felt paralyzed by a strange mixture of longing and suffocating dread.', 'translation': 'Jonathan garip bir arzu ve boğucu bir dehşet karışımıyla adeta felç olmuş hissetti.', 'notes': 'suffocating dread: boğucu dehşet.'}, {'id': 92, 'text': 'As she bent her head, Jonathan saw her red lips part to reveal long, razor-sharp canine teeth.', 'translation': 'Kadın başını eğerken Jonathan onun kırmızı dudaklarının aralandığını ve jilet gibi keskin uzun köpek dişlerini gördü.', 'notes': 'razor-sharp canine teeth: jilet gibi keskin köpek dişleri.'}, {'id': 93, 'text': 'Her sweet breath smelled faintly of copper and ancient dust as she leaned closer to his bare throat.', 'translation': 'Çıplak boğazına daha da yaklaşırken tatlı nefesi hafifçe bakır ve kadim toz kokuyordu.', 'notes': 'bare throat: çıplak boğaz.'}, {'id': 94, 'text': 'Just as her fangs grazed his skin, the chamber door burst open with a resounding crash!', 'translation': 'Tam sivri dişleri tenine değmişti ki odanın kapısı kulakları sağır eden bir gümbürtüyle ardına kadar açıldı!', 'notes': 'resounding crash: yankılanan gümbürtü.'}, {'id': 95, 'text': 'Count Dracula rushed into the room, his eyes blazing like volcanic coals with terrifying fury.', 'translation': 'Kont Drakula gözleri korkunç bir öfkeyle volkanik kor gibi alev alev yanarak odaya daldı.', 'notes': 'volcanic coals: volkanik korlar.'}, {'id': 96, 'text': 'With an iron grip, Dracula seized the fair vampire by the neck and hurled her violently across the chamber.', 'translation': 'Demir gibi bir kavrayışla Drakula sarışın vampiri boynundan yakaladı ve şiddetle odanın öteki ucuna fırlattı.', 'notes': 'iron grip: demir gibi kavrayış.'}, {'id': 97, 'text': '"How dare you touch him when I have forbidden it?" Dracula roared, his voice shaking the stone walls.', 'translation': '"Ben yasaklamışken ona dokunmaya nasıl cüret edersiniz?" diye kükredi Drakula; sesi taş duvarları titretiyordu.', 'notes': 'shaking stone walls: taş duvarları sarsan.'}, {'id': 98, 'text': '"This man belongs to me! Back, I tell you; you shall have him when I am done with him!"', 'translation': '"Bu adam bana ait! Geri çekilin diyorum; benim onunla işim bittiğinde o sizin olacak!"', 'notes': 'done with him: onunla işi bittiğinde.'}, {'id': 99, 'text': 'Dracula tossed a squirming burlap sack onto the floor, from which came the muffled cry of an innocent child.', 'translation': 'Drakula yere kıpırdayan bir çuval fırlattı; içinden masum bir çocuğun boğuk ağlaması geliyordu.', 'notes': 'squirming burlap sack: kıpırdanan çuval.'}, {'id': 100, 'text': 'The three vampire women fell upon the bundle with eager shrieks and dissolved through the walls into the night.', 'translation': 'Üç vampir kadın hevesli çığlıklarla çıkının üzerine üşüştüler ve duvarların arasından gecenin içine eriyip gittiler.', 'notes': 'dissolved through walls: duvarların arasından eriyip gitti.'}]}, {'page_no': 6, 'title': 'Earth Boxes and the Desperate Leap', 'tr_title': 'Toprak Sandıkları ve Çaresiz Kaçış', 'vocab_focus': [('dictate', 'dikte etmek, yazdırmak'), ('postdated', 'ileri tarihli'), ('gypsies', 'çingeneler'), ('coffin', 'tabut'), ('consecrated', 'kutsanmış'), ('paralyzed', 'felç olmuş, donakalmış'), ('climbing', 'tırmanma'), ('escape', 'kaçış')], 'sentences': [{'id': 101, 'text': 'Jonathan woke in his own bed the following morning, uncertain whether the horror had been reality or a nightmare.', 'translation': 'Ertesi sabah Jonathan kendi yatağında uyandı; yaşanan dehşetin gerçek mi yoksa bir kâbus mu olduğundan emin değildi.', 'notes': 'uncertain whether: emin olamayarak.'}, {'id': 102, 'text': 'Later that day, Count Dracula commanded Jonathan to write three postdated letters to his firm and his fiancée Mina.', 'translation': "O günün ilerleyen saatlerinde Kont Drakula, şirketine ve nişanlısı Mina'ya ileri tarihli üç mektup yazmasını Jonathan'a emretti.", 'notes': 'postdated letters: ileri tarihli mektuplar.'}, {'id': 103, 'text': 'The letters stated that Jonathan had completed his legal business and was journeying safely back to England.', 'translation': "Mektuplar Jonathan'ın hukuki işlerini tamamladığını ve güvenle İngiltere'ye dönmekte olduğunu belirtiyordu.", 'notes': 'legal business: hukuki işler.'}, {'id': 104, 'text': 'Jonathan knew that the date of the final letter would mark the day of his intended execution.', 'translation': 'Jonathan son mektubun tarihinin kendi planlanan idam gününü simgeleyeceğini biliyordu.', 'notes': 'intended execution: planlanan infaz/ölüm.'}, {'id': 105, 'text': 'Soon afterward, a band of rugged Slovak gypsies arrived in the courtyard with heavy wooden wagons.', 'translation': 'Kısa bir süre sonra, ağır tahta vagonlarla bir grup çetin Slovak çingene kalenin avlusuna vardı.', 'notes': 'wooden wagons: tahta vagonlar.'}, {'id': 106, 'text': 'They unloaded fifty massive rectangular wooden boxes and carried them down into the subterranean vaults.', 'translation': 'Elli adet devasa dikdörtgen tahta sandığı indirdiler ve yeraltı mahzenlerine taşıdılar.', 'notes': 'subterranean vaults: yeraltı mahzenleri.'}, {'id': 107, 'text': 'Desperate for any clue, Jonathan crept down a ruined staircase leading to the ancient castle chapel.', 'translation': 'Herhangi bir ipucu bulmak için can atan Jonathan, eski şato şapeline inen harap bir merdivenden aşağı süzüldü.', 'notes': 'castle chapel: şato şapeli.'}, {'id': 108, 'text': 'The crypt smelled intensely of freshly turned moldy soil and the decaying dust of ancient tombs.', 'translation': 'Kripta yoğun bir şekilde taze kazılmış küflü toprak ve kadim mezarların çürüyen tozu kokuyordu.', 'notes': 'decaying dust: çürüyen toz.'}, {'id': 109, 'text': 'There, lying inside one of the wooden boxes upon a bed of Transylvanian earth, lay Count Dracula himself!', 'translation': 'İşte orada, Transilvanya toprağından bir yatak üzerine serilmiş ahşap sandıklardan birinin içinde bizzat Kont Drakula yatıyordu!', 'notes': 'bed of earth: toprak yatak.'}, {'id': 110, 'text': 'His eyes were wide open and fixed in a glassy, lifeless stare, yet his face showed no signs of death.', 'translation': 'Gözleri faltaşı gibi açıktı ve donuk, cansız bir bakışla dikilmişti; ancak yüzünde ölümden hiçbir iz yoktu.', 'notes': 'glassy stare: donuk/cam gibi bakış.'}, {'id': 111, 'text': 'His cheeks were full and ruddy, his white hair had turned dark iron-grey, and he looked decades younger.', 'translation': 'Yanakları dolgun ve al aldı, beyaz saçları koyu demir grisine dönmüştü ve onlarca yıl daha genç görünüyordu.', 'notes': 'looked decades younger: onlarca yıl daha genç görünüyordu.'}, {'id': 112, 'text': 'From the corners of his cruel red mouth, fresh warm blood trickled down his chin and stained his collar.', 'translation': 'Zalim kırmızı ağzının kenarlarından taze sıcak kan çenesine doğru akıyor ve yakasını lekeliyordu.', 'notes': 'fresh warm blood: taze sıcak kan.'}, {'id': 113, 'text': 'The monster had fed on human victims and was sleeping like a gorged leech upon his consecrated native earth.', 'translation': 'Canavar insan kurbanlarla beslenmişti ve kutsal vatan toprağının üzerinde doymuş bir sülük gibi uyuyordu.', 'notes': 'gorged leech: doymuş/şişmiş sülük.'}, {'id': 114, 'text': "Seizing a heavy shovel from the corner, Jonathan raised the iron blade to cleave the demon's skull.", 'translation': 'Köşeden ağır bir kürek kapan Jonathan, iblisin kafatasını yarmak için demir ağzı havaya kaldırdı.', 'notes': "cleave demon's skull: iblisin kafatasını yarmak."}, {'id': 115, 'text': "Just as he struck, the Count's head seemed to turn slightly, his hypnotic eyes fixing Jonathan with burning fury.", 'translation': "Tam vuracağı sırada Kont'un başı hafifçe dönmüş gibi oldu; büyüleyici gözleri yanan bir öfkeyle Jonathan'a dikildi.", 'notes': 'burning fury: alev alev öfke.'}, {'id': 116, 'text': "The shovel slipped from Jonathan's trembling hands, grazing the monster's forehead without doing fatal damage.", 'translation': "Kürek Jonathan'ın titreyen ellerinden kaydı ve ölümcül bir hasar vermeden canavarın alnını sıyırdı.", 'notes': 'fatal damage: ölümcül hasar.'}, {'id': 117, 'text': 'Terrified, Jonathan fled back to his chamber as the heavy stone door of the crypt swung shut with a boom.', 'translation': 'Dehşete düşen Jonathan odasına geri kaçtı; kriptanın ağır taş kapısı bir gümbürtüyle arkasından kapandı.', 'notes': 'swung shut: çarparak kapandı.'}, {'id': 118, 'text': 'The wagons departed Castle Dracula carrying the fifty boxes toward the Danube river, bound for England.', 'translation': "Vagonlar İngiltere'ye gönderilmek üzere elli sandığı Tuna nehrine doğru taşıyarak Drakula Şatosu'ndan ayrıldı.", 'notes': 'bound for England: İngiltere yolcusu.'}, {'id': 119, 'text': 'Left behind to be devoured by the three vampire women, Jonathan chose the desperate risk of death over dishonor.', 'translation': 'Üç vampir kadın tarafından yutulmak üzere geride bırakılan Jonathan, onursuzluk yerine çaresizce ölümü göze aldı.', 'notes': 'chose risk of death: ölüm riskini seçti.'}, {'id': 120, 'text': 'Kneeling in prayer, he stepped onto the outer window ledge and began the perilous descent down the castle precipice.', 'translation': 'Dua ederek diz çöktü, dış pencere pervazına adım attı ve kalenin o tehlikeli uçurumundan aşağıya doğru inişe başladı.', 'notes': 'perilous descent: tehlikeli iniş.'}]}, {'page_no': 7, 'title': 'Mina and Lucy in Whitby', 'tr_title': "Whitby'de Mina ve Lucy", 'vocab_focus': [('suitor', 'talip, talip olan kişi'), ('proposal', 'evlilik teklifi'), ('fiancé', 'nişanlı'), ('headland', 'burun, yalıyar'), ('sleepwalking', 'uyurgezerlik'), ('cemetery', 'mezarlık'), ('anxiety', 'endişe, kaygı'), ('tombstone', 'mezar taşı')], 'sentences': [{'id': 121, 'text': 'Across the sea in England, Mina Murray spent anxious weeks waiting for word from her beloved fiancé.', 'translation': "Denizin öte yakasında, İngiltere'de Mina Murray sevgili nişanlısından bir haber bekleyerek endişeli haftalar geçirdi.", 'notes': 'anxious weeks: endişeli haftalar.'}, {'id': 122, 'text': "Jonathan's letters had ceased abruptly, leaving Mina tormented by dark premonitions of danger.", 'translation': "Jonathan'ın mektupları aniden kesilmişti; bu durum Mina'yı yaklaşan tehlikenin kara önsezileriyle kıvrandırıyordu.", 'notes': 'premonitions of danger: tehlike önsezileri.'}, {'id': 123, 'text': 'To distract her troubled mind, Mina accepted an invitation to visit her closest friend, Lucy Westenra.', 'translation': "Huzursuz zihnini dağıtmak için Mina, en yakın arkadaşı Lucy Westenra'yı ziyaret etme davetini kabul etti.", 'notes': 'distract troubled mind: huzursuz zihni dağıtmak.'}, {'id': 124, 'text': 'Lucy was staying for the summer at the picturesque seaside port of Whitby on the Yorkshire coast.', 'translation': "Lucy yazı Yorkshire kıyısındaki pitoresk sahil limanı Whitby'de geçiriyordu.", 'notes': 'picturesque seaside port: kartpostal gibi sahil limanı.'}, {'id': 125, 'text': 'Lucy was nineteen, radiant with youth, gentle-hearted, and extraordinarily attractive.', 'translation': 'Lucy on dokuz yaşındaydı, gençlikle ışıl ışıldı, narin yürekliydi ve olağanüstü çekiciydi.', 'notes': 'radiant with youth: gençlikle parıldayan.'}, {'id': 126, 'text': 'In a single remarkable day, she had received three separate marriage proposals from three distinguished suitors.', 'translation': 'Kayda değer tek bir günde üç seçkin talipten üç ayrı evlilik teklifi almıştı.', 'notes': 'marriage proposals: evlilik teklifleri.'}, {'id': 127, 'text': 'The first was Dr. John Seward, the intelligent young superintendent of a large mental asylum in Purfleet.', 'translation': "İlki, Purfleet'teki büyük bir akıl hastanesinin zeki genç başhekimi Doktor John Seward'dı.", 'notes': 'mental asylum: akıl hastanesi.'}, {'id': 128, 'text': 'The second was Quincey Morris, an honorable, brave, and wealthy adventurer from Texas.', 'translation': "İkincisi, Teksaslı onurlu, cesur ve varlıklı bir maceracı olan Quincey Morris'ti.", 'notes': 'wealthy adventurer: varlıklı maceracı.'}, {'id': 129, 'text': 'The third was Arthur Holmwood, the handsome son of Lord Godalming, whom Lucy loved with all her heart.', 'translation': "Üçüncüsü ise Lucy'nin tüm kalbiyle sevdiği, Lord Godalming'in yakışıklı oğlu Arthur Holmwood'du.", 'notes': 'with all her heart: tüm kalbiyle.'}, {'id': 130, 'text': 'Lucy accepted Arthur with radiant happiness, while Seward and Quincey pledged their eternal devotion as loyal friends.', 'translation': "Lucy ışıl ışıl bir mutlulukla Arthur'u kabul etti; Seward ve Quincey ise sadık dostlar olarak ömür boyu bağlılık yemini ettiler.", 'notes': 'eternal devotion: ebedi bağlılık.'}, {'id': 131, 'text': 'Yet despite her joyful engagement, Lucy had recently resumed an old and dangerous childhood habit.', 'translation': 'Fakat neşeli nişanına rağmen Lucy, son zamanlarda çocukluğundan kalma eski ve tehlikeli bir alışkanlığa yeniden başlamıştı.', 'notes': 'childhood habit: çocukluk alışkanlığı.'}, {'id': 132, 'text': 'She had begun sleepwalking at night, rising from her bed while fast asleep and wandering out into the dark.', 'translation': 'Geceleri uyurgezerlik yapmaya, derin uykudayken yatağından kalkıp karanlığa doğru yürümeye başlamıştı.', 'notes': 'fast asleep: derin uykuda.'}, {'id': 133, 'text': 'Mina locked the bedroom door each night and tied the key to her own wrist to ensure Lucy remained safe.', 'translation': "Mina her gece yatak odasının kapısını kilitliyor ve Lucy'nin güvende kalmasını sağlamak için anahtarı kendi bileğine bağlıyordu.", 'notes': 'tied key to wrist: anahtarı bileğe bağladı.'}, {'id': 134, 'text': 'During the sunny afternoons, the two friends loved walking up the ninety-nine stone steps to the ancient abbey.', 'translation': 'Güneşli öğleden sonralarında iki arkadaş kadim manastıra çıkan doksan dokuz taş basamağı tırmanmayı çok seviyordu.', 'notes': 'stone steps: taş basamaklar.'}, {'id': 135, 'text': 'The ruined Benedictine abbey stood perched high upon the East Cliff, overlooking the bustling harbor and the sea.', 'translation': "Harap Benedikten manastırı hareketli limana ve denize bakan Doğu Yalıyarı'nın tepesinde tünemiş gibi duruyordu.", 'notes': 'perched high: yüksekte tünemiş/konuşlanmış.'}, {'id': 136, 'text': 'Surrounding the abbey was the parish churchyard, filled with weathered, moss-covered tombstones.', 'translation': 'Manastırın etrafında, rüzgârdan aşınmış ve yosun tutmuş mezar taşlarıyla dolu cemaat mezarlığı vardı.', 'notes': 'moss-covered tombstones: yosun kaplı mezar taşları.'}, {'id': 137, 'text': "Lucy's favorite spot was a weathered wooden bench placed beside the edge of the high cliff.", 'translation': "Lucy'nin en sevdiği yer, yüksek kayalığın tam kenarına yerleştirilmiş yıpranmış ahşap bir banktı.", 'notes': 'weathered wooden bench: yıpranmış ahşap bank.'}, {'id': 138, 'text': 'From this vantage point, they could watch the fishing boats sailing into port as the sun sank in the west.', 'translation': 'Bu seyir noktasından, batıda güneş batarken limana yanaşan balıkçı teknelerini izleyebiliyorlardı.', 'notes': 'vantage point: seyir noktası.'}, {'id': 139, 'text': 'An old retired fisherman named Mr. Swales often sat with them, telling grim folklore of shipwrecks and ghosts.', 'translation': 'Bay Swales adında emekli yaşlı bir balıkçı sık sık yanlarına oturur, gemi batıkları ve hayaletlerle ilgili ürpertici efsaneler anlatırdı.', 'notes': 'grim folklore: ürpertici halk masalları/efsaneleri.'}, {'id': 140, 'text': 'As August began, the weather suddenly shifted, and an oppressive, unnatural stillness settled over the sea.', 'translation': 'Ağustos başlarken hava ansızın değişti ve denizin üzerine boğucu, tekinsiz bir durgunluk çöktü.', 'notes': 'unnatural stillness: tekinsiz/doğal olmayan durgunluk.'}]}, {'page_no': 8, 'title': 'The Storm and the Ghost Ship Demeter', 'tr_title': 'Fırtına ve Hayalet Gemi Demeter', 'vocab_focus': [('schooner', 'uskuna, yelkenli gemi'), ('tempest', 'şiddetli fırtına'), ('rudder', 'dümen'), ('corpse', 'ceset'), ('hound', 'tazı, iri köpek'), ('carnage', 'katliam'), ('cargo', 'kargo, yük'), ('vanish', 'gözden kaybolmak')], 'sentences': [{'id': 141, 'text': 'On the evening of August eighth, a sudden and terrifying tempest swept across the Yorkshire coast.', 'translation': 'Sekiz Ağustos akşamında ani ve dehşet verici bir fırtına Yorkshire kıyılarını kasıp kavurdu.', 'notes': 'terrifying tempest: dehşet verici fırtına.'}, {'id': 142, 'text': 'Heavy black clouds enveloped the sky, turning the sea into a boiling cauldron of violent waves.', 'translation': 'Ağır kara bulutlar gökyüzünü kapladı ve denizi azgın dalgaların kaynayan bir kazanına dönüştürdü.', 'notes': 'boiling cauldron: kaynayan kazan.'}, {'id': 143, 'text': 'Through the swirling mist and driving rain, the townspeople spotted a foreign schooner rushing helplessly toward the rocks.', 'translation': 'Girdap gibi dönen sis ve kırbaçlayan yağmurun arasından kasaba halkı kayalıklara doğru çaresizce sürüklenen yabancı bir uskuna fark etti.', 'notes': 'foreign schooner: yabancı uskuna.'}, {'id': 144, 'text': 'Every sail was set, and the vessel flew before the howling gale like a phantom ship upon the churning water.', 'translation': 'Bütün yelkenleri açıktı ve tekne, çalkantılı suların üzerinde bir hayalet gemi gibi uğuldayan fırtınanın önünde uçarcasına ilerliyordu.', 'notes': 'phantom ship: hayalet gemi.'}, {'id': 145, 'text': 'By a miracle of navigation, the ship cleared the dangerous harbor entrance and drove hard onto the sandy shore.', 'translation': 'Bir denizcilik mucizesi eseri olarak gemi tehlikeli liman girişini aştı ve kumluk sahile sertçe oturdu.', 'notes': 'miracle of navigation: denizcilik mucizesi.'}, {'id': 146, 'text': 'The moment the vessel touched the sand, an immense black dog bounded out from the deck onto the beach.', 'translation': 'Tekne kuma değer değmez devasa siyah bir köpek güverteden kumsala fırladı.', 'notes': 'bounded out: fırladı, sıçradı.'}, {'id': 147, 'text': 'The great beast sprinted up the cliffside steps and vanished into the darkness of the churchyard above.', 'translation': 'Koca canavar yalıyar basamaklarını hızla tırmandı ve yukarıdaki mezarlığın karanlığında gözden kayboldu.', 'notes': 'sprinted up: hızla tırmandı.'}, {'id': 148, 'text': 'Coastguards and spectators rushed aboard the stranded vessel and discovered a horrifying spectacle.', 'translation': 'Sahil güvenlik ve meraklılar karaya oturan gemiye koştular ve korkunç bir manzarayla karşılaştılar.', 'notes': 'horrifying spectacle: korkunç manzara.'}, {'id': 149, 'text': "The captain was dead, his corpse lashed firmly to the ship's wheel with strong ropes.", 'translation': 'Kaptan ölmüştü; cesedi sağlam halatlarla geminin dümenine sıkı sıkıya bağlanmıştı.', 'notes': 'lashed to the wheel: dümene bağlanmış.'}, {'id': 150, 'text': 'Between his stiff, frozen fingers, the dead captain clasped a small crucifix and a wooden bead rosary.', 'translation': 'Kaskatı kesilmiş donuk parmaklarının arasında ölü kaptan küçük bir haç ve tahta taneli bir tespih tutuyordu.', 'notes': 'stiff fingers: kaskatı parmaklar.'}, {'id': 151, 'text': 'There was not a single living soul aboard the ship; the entire crew had vanished without a trace.', 'translation': 'Gemide tek bir canlı ruh bile yoktu; bütün mürettebat iz bırakmadan kaybolmuştu.', 'notes': 'vanished without a trace: iz bırakmadan kayboldu.'}, {'id': 152, 'text': 'The ship was identified as the Demeter, registered in the Russian port of Varna on the Black Sea.', 'translation': "Geminin Karadeniz'deki Rus limanı Varna'ya kayıtlı Demeter olduğu belirlendi.", 'notes': 'identified as: olarak teşhis edildi.'}, {'id': 153, 'text': "The coastguard recovered the captain's private pocket log, which revealed a chilling record of terror at sea.", 'translation': 'Sahil güvenlik, denizde yaşanan kan dondurucu bir dehşeti gözler önüne seren kaptanın özel cep seyir defterini ele geçirdi.', 'notes': 'chilling record: kan dondurucu kayıt.'}, {'id': 154, 'text': 'The log described how, after leaving the Black Sea, a tall, gaunt stranger had been sighted lurking aboard.', 'translation': "Seyir defteri, Karadeniz'den ayrıldıktan sonra gemide pusuya yatmış uzun boylu, bir deri bir kemik bir yabancının nasıl görüldüğünü anlatıyordu.", 'notes': 'lurking aboard: gemide pusuya yatan.'}, {'id': 155, 'text': 'One by one, the sailors on the night watch had disappeared mysteriously into the empty ocean.', 'translation': 'Gece nöbetindeki denizciler teker teker esrarengiz bir şekilde ıssız okyanusta kaybolmuştu.', 'notes': 'night watch: gece nöbeti.'}, {'id': 156, 'text': 'In his final desperate entry, the captain wrote: "He is here with me; I shall lash myself to the helm until the end!"', 'translation': 'Son çaresiz notunda kaptan şöyle yazmıştı: "O burada benimle; sonuna kadar kendimi dümene bağlayacağım!"', 'notes': 'lash myself to the helm: kendimi dümene bağlamak.'}, {'id': 157, 'text': 'Inspectors examined the hold of the Demeter and found that its only cargo was fifty wooden boxes.', 'translation': "Müfettişler Demeter'in ambarını incelediler ve tek yükünün elli tahta sandık olduğunu gördüler.", 'notes': 'only cargo: yegane yük.'}, {'id': 158, 'text': 'The boxes were packed entirely with common earth, consigned to a lawyer named Mr. Hawkins in London.', 'translation': "Sandıklar tamamen sıradan toprakla doldurulmuştu ve Londra'daki Bay Hawkins adında bir avukata gönderilmişti.", 'notes': 'common earth: sıradan toprak.'}, {'id': 159, 'text': 'No one in Whitby could explain why a foreign vessel would transport boxes of dirt across the continent.', 'translation': "Whitby'deki hiç kimse yabancı bir teknenin neden kıtalar boyu toprak sandıkları taşıdığını açıklayamadı.", 'notes': 'transport dirt: toprak taşımak.'}, {'id': 160, 'text': 'Nor did anyone suspect that the ancient evil of Transylvania had stepped ashore upon the soil of England.', 'translation': "Transilvanya'nın o kadim kötülüğünün İngiltere topraklarına ayak bastığından ise kimsenin şüphesi yoktu.", 'notes': 'stepped ashore: karaya ayak bastı.'}]}, {'page_no': 9, 'title': 'The Midnight Shadow on the Cliff', 'tr_title': 'Kayalıktaki Gece Yarısı Gölgesi', 'vocab_focus': [('nightdress', 'gecelik'), ('silhouette', 'silüet, gölge'), ('puncture', 'delik, batma'), ('pinprick', 'iğne batması izi'), ('languid', 'halsiz, bitkin'), ('pallor', 'solgunluk, solukluk'), ('torment', 'ıstırap, eziyet'), ('bench', 'bank, oturak')], 'sentences': [{'id': 161, 'text': "A few nights after the Russian ship wrecked, Mina awoke suddenly at two o'clock in the morning.", 'translation': 'Rus gemisinin batmasından birkaç gece sonra Mina gece saat ikide aniden uyandı.', 'notes': 'awoke suddenly: aniden uyandı.'}, {'id': 162, 'text': "The bedroom door was slightly ajar, the key hung untouched upon her wrist, and Lucy's bed was completely empty.", 'translation': "Yatak odasının kapısı aralıktı, anahtar bileğinde el değmemiş halde duruyordu ve Lucy'nin yatağı bomboştu.", 'notes': 'slightly ajar: hafifçe aralık.'}, {'id': 163, 'text': 'Terrified that her friend might walk over the dangerous cliff edge in her sleep, Mina grabbed a shawl and rushed out.', 'translation': 'Arkadaşının uykusunda tehlikeli uçurumun kenarından düşebileceğinden dehşete düşen Mina bir şal kapıp dışarı fırladı.', 'notes': 'cliff edge: uçurum kenarı.'}, {'id': 164, 'text': 'The streets of Whitby were dark and deserted as Mina ran frantically toward the stone steps of the East Cliff.', 'translation': "Mina panikle Doğu Yalıyarı'nın taş basamaklarına doğru koşarken Whitby sokakları karanlık ve ıssızdı.", 'notes': 'ran frantically: panik içinde koştu.'}, {'id': 165, 'text': 'Reaching the summit, the silver moonlight broke through the clouds, illuminating the ancient abbey churchyard.', 'translation': 'Zirveye ulaştığında gümüş ay ışığı bulutların arasından süzülerek kadim manastır mezarlığını aydınlattı.', 'notes': 'illuminating: aydınlatarak.'}, {'id': 166, 'text': "Far ahead on Lucy's favorite bench, Mina spotted a snow-white figure reclining motionless against the wood.", 'translation': "İleride, Lucy'nin en sevdiği bankın üzerinde Mina tahtaya yaslanmış bembeyaz ve hareketsiz yatan bir siluet fark etti.", 'notes': 'reclining motionless: hareketsizce yaslanan.'}, {'id': 167, 'text': "Bending over the sleeping girl was a tall, dark silhouette, whose head was pressed against Lucy's neck.", 'translation': "Uyuyan kızın üzerine eğilmiş, başını Lucy'nin boynuna dayamış uzun boylu, karanlık bir siluet vardı.", 'notes': 'bending over: üzerine eğilen.'}, {'id': 168, 'text': "As Mina screamed Lucy's name, the dark figure raised a pale face with burning red eyes and vanished like a shadow.", 'translation': "Mina Lucy'nin adını haykırdığında, o karanlık figür yanan kırmızı gözlü solgun bir yüz kaldırdı ve bir gölge gibi kayboldu.", 'notes': 'burning red eyes: yanan kızıl gözler.'}, {'id': 169, 'text': 'Mina reached the bench out of breath and found Lucy shivering violently in her thin white nightdress.', 'translation': "Nefes nefese banka ulaşan Mina, Lucy'yi ince beyaz geceliği içinde tir tir titrerken buldu.", 'notes': 'shivering violently: şiddetle titreyerek.'}, {'id': 170, 'text': 'Lucy was still fast asleep, murmuring incoherently and breathing with labored gasps.', 'translation': 'Lucy hâlâ derin uykudaydı; anlaşılmaz şeyler mırıldanıyor ve güçlükle nefes alıyordu.', 'notes': 'labored gasps: güçlükle alınan nefesler.'}, {'id': 171, 'text': "Mina wrapped her warm wool coat around Lucy's shivering shoulders and fastened it securely.", 'translation': "Mina sıcak yün paltosunu Lucy'nin titreyen omuzlarına sardı ve sıkıca ilikledi.", 'notes': 'fastened securely: sıkıca tutturdu/ilikledi.'}, {'id': 172, 'text': "While fastening the collar, Mina noticed two tiny puncture marks on the side of Lucy's slender throat.", 'translation': "Yakayı iliklerken Mina Lucy'nin narin boğazının yan tarafında iki küçük delik izi fark etti.", 'notes': 'two tiny puncture marks: iki minik delik izi.'}, {'id': 173, 'text': 'A single drop of crimson blood stained the pale skin between the two red pinpricks.', 'translation': 'İki kızıl iğne deliği arasındaki solgun teni tek bir kızıl kan damlası lekelemişti.', 'notes': 'crimson blood: koyu kırmızı kan.'}, {'id': 174, 'text': 'Assuming she had accidentally pricked Lucy with a safety pin in her haste, Mina led her friend safely home.', 'translation': "Telaş içinde Lucy'ye kazara çengelli iğne batırdığını varsayan Mina arkadaşını güvenle eve götürdü.", 'notes': 'pricked with safety pin: çengelli iğne batırmak.'}, {'id': 175, 'text': "Over the following week, Lucy's lively demeanor withered into alarming weakness and perpetual lethargy.", 'translation': "Takip eden hafta boyunca Lucy'nin canlı hali yerini endişe verici bir zayıflığa ve dinmeyen bir uyuşukluğa bıraktı.", 'notes': 'alarming weakness: endişe verici halsizlik.'}, {'id': 176, 'text': 'Her cheeks lost all natural color, turning a waxy, ghostlike pallor that frightened everyone in the household.', 'translation': 'Yanakları tüm doğal rengini kaybetti ve evdeki herkesi korkutan balmumu gibi hayaletsi bir solgunluğa büründü.', 'notes': 'ghostlike pallor: hayaletsi solgunluk.'}, {'id': 177, 'text': 'She spoke softly of strange, seductive dreams in which red eyes watched her through fluttering mists.', 'translation': 'Dalgalanan sislerin arasından kırmızı gözlerin kendisini izlediği tuhaf, baştan çıkarıcı rüyalardan usulca söz ediyordu.', 'notes': 'fluttering mists: dalgalanan sisler.'}, {'id': 178, 'text': 'Just as Mina was overwhelmed with worry, she received an unexpected telegram from a hospital in Budapest.', 'translation': "Tam Mina endişeden kahrolurken Budapeşte'deki bir hastaneden beklenmedik bir telgraf aldı.", 'notes': 'unexpected telegram: beklenmedik telgraf.'}, {'id': 179, 'text': 'Jonathan Harker had been discovered wandering the Hungarian frontier, suffering from severe brain fever and delirium.', 'translation': "Jonathan Harker'ın Macaristan sınırında şiddetli beyin humması ve hezeyan içinde dolaşırken bulunduğu bildiriliyordu.", 'notes': 'brain fever: beyin humması/iltihabı.'}, {'id': 180, 'text': 'Relieved that her fiancé was alive, Mina packed her bags immediately and caught the first train toward the continent.', 'translation': 'Nişanlısının hayatta olduğunu öğrenip rahatlayan Mina bavullarını derhal topladı ve kıtaya giden ilk trene bindi.', 'notes': 'caught the first train: ilk trene bindi.'}]}, {'page_no': 10, 'title': "Renfield's Madness and the Great Specialist", 'tr_title': "Renfield'nin Çılgınlığı ve Büyük Uzman", 'vocab_focus': [('asylum', 'tımarhane, akıl hastanesi'), ('zoophagous', 'canlı hayvan yiyen'), ('spider', 'örümcek'), ('sparrow', 'serçe'), ('specialist', 'uzman tabip'), ('diagnosis', 'teşhis'), ('consultation', 'tıbbi danışma, konsültasyon'), ('lethargy', 'uyuşukluk, halsizlik')], 'sentences': [{'id': 181, 'text': 'While Mina journeyed to Hungary, Dr. John Seward was managing his private mental asylum in Purfleet, Essex.', 'translation': "Mina Macaristan'a doğru yol alırken Doktor John Seward Purfleet, Essex'teki özel akıl hastanesini yönetiyordu.", 'notes': 'managing private asylum: özel akıl hastanesini yönetmek.'}, {'id': 182, 'text': 'His most perplexing patient was a middle-aged man named R. M. Renfield, who exhibited unique mental symptoms.', 'translation': 'En kafa karıştırıcı hastası, eşsiz zihinsel belirtiler sergileyen R. M. Renfield adında orta yaşlı bir adamdı.', 'notes': 'perplexing patient: kafa karıştırıcı hasta.'}, {'id': 183, 'text': 'Dr. Seward classified Renfield as a zoophagous maniac—a creature driven by a compulsive desire to consume living beings.', 'translation': "Doktor Seward Renfield'ı canlı hayvan yiyen bir manyak—canlı varlıkları tüketmeye yönelik takıntılı bir arzuyla hareket eden biri—olarak sınıflandırdı.", 'notes': 'zoophagous maniac: canlı varlık yiyen deli.'}, {'id': 184, 'text': 'Renfield first caught hundreds of buzzing flies, feeding them methodically to a colony of fat garden spiders.', 'translation': 'Renfield önce vızıldayan yüzlerce sinek yakaladı ve onları şişman bahçe örümceklerinden oluşan bir koloniye düzenli olarak yedirdi.', 'notes': 'colony of spiders: örümcek kolonisi.'}, {'id': 185, 'text': 'He then captured sparrows from the window ledge, feeding the spiders to the birds before devouring the sparrows raw.', 'translation': 'Daha sonra pencere pervazındaki serçeleri yakaladı; serçeleri çiğ çiğ yemeden önce örümcekleri kuşlara yedirdi.', 'notes': 'devouring raw: çiğ çiğ yutmak/tüketmek.'}, {'id': 186, 'text': '"The blood is the life!" Renfield screamed wildly when the doctor confiscated his gruesome menagerie.', 'translation': 'Doktor onun bu korkunç hayvan koleksiyonuna el koyduğunda Renfield çılgınca "Kan candır!" diye bağırdı.', 'notes': 'the blood is the life: kan hayattır/candır.'}, {'id': 187, 'text': 'Renfield claimed that by consuming multiple lives, he absorbed their vital energy into his own physical form.', 'translation': 'Renfield birden çok canı tüketerek onların yaşam enerjisini kendi bedenine kattığını iddia ediyordu.', 'notes': 'absorbed vital energy: yaşam enerjisini emdi.'}, {'id': 188, 'text': "Seward's scientific observations were interrupted by an urgent telegram from his dear friend Arthur Holmwood.", 'translation': "Seward'ın bilimsel gözlemleri sevgili dostu Arthur Holmwood'dan gelen acil bir telgrafla bölündü.", 'notes': 'urgent telegram: acil telgraf.'}, {'id': 189, 'text': 'Arthur begged Seward to examine Lucy in London, where she had returned from Whitby in desperate health.', 'translation': "Arthur Whitby'den vahim bir sağlık durumuyla Londra'ya dönen Lucy'yi muayene etmesi için Seward'a yalvardı.", 'notes': 'desperate health: vahim sağlık durumu.'}, {'id': 190, 'text': 'When Seward examined Lucy at her home, he was appalled by the catastrophic deterioration of her constitution.', 'translation': "Seward Lucy'yi evinde muayene ettiğinde kızın bünyesindeki feci çöküş karşısında dehşete düştü.", 'notes': 'catastrophic deterioration: feci çöküş/kötüleşme.'}, {'id': 191, 'text': 'She was suffering from severe blood loss, yet there was no sign of internal bleeding or ordinary hemorrhage.', 'translation': 'Ciddi bir kan kaybı çekiyordu fakat iç kanama ya da sıradan bir kanama emaresi yoktu.', 'notes': 'blood loss: kan kaybı.'}, {'id': 192, 'text': 'Confounded by the mystery, Seward wired his former mentor, Professor Abraham Van Helsing of Amsterdam University.', 'translation': "Bu gizem karşısında ne yapacağını bilemeyen Seward, Amsterdam Üniversitesi'nden eski hocası Profesör Abraham Van Helsing'e telgraf çekti.", 'notes': 'confounded by mystery: gizem karşısında şaşırmış.'}, {'id': 193, 'text': 'Van Helsing was an eminent philosopher, physician, and expert in rare diseases and obscure historical folklore.', 'translation': 'Van Helsing seçkin bir filozof, hekim ve nadir hastalıklar ile gizemli tarihi efsaneler konusunda bir uzmandı.', 'notes': 'eminent physician: seçkin hekim.'}, {'id': 194, 'text': "Recognizing the gravity of the situation from Seward's description, the Dutch professor boarded the mail packet immediately.", 'translation': "Seward'ın anlattıklarından durumun ciddiyetini anlayan Hollandalı profesör derhal posta vapuruna bindi.", 'notes': 'boarded mail packet: posta vapuruna bindi.'}, {'id': 195, 'text': "Upon arriving in London, Van Helsing went straight to Lucy's bedside, examining her pale gums and throat.", 'translation': "Londra'ya varır varmaz Van Helsing doğruca Lucy'nin başucuna gitti; solgun diş etlerini ve boğazını muayene etti.", 'notes': 'went straight to bedside: doğruca başucuna gitti.'}, {'id': 196, 'text': 'He closely inspected the two puncture wounds on her throat, which appeared inflamed and refused to heal.', 'translation': 'Boğazındaki iltihaplı görünen ve bir türlü iyileşmeyen iki delik yarasını yakından inceledi.', 'notes': 'refused to heal: iyileşmeyi reddetti / iyileşmedi.'}, {'id': 197, 'text': "The professor's broad forehead furrowed with profound alarm, though he concealed his fears from Arthur.", 'translation': "Korkularını Arthur'dan gizlemesine rağmen profesörün geniş alnı derin bir endişeyle kırıştı.", 'notes': 'broad forehead furrowed: geniş alnı kırıştı.'}, {'id': 198, 'text': '"This is no disease that ordinary medicine can cure," Van Helsing whispered gravely to Seward in private.', 'translation': '"Bu sıradan tıbbın iyileştirebileceği bir hastalık değil," diye fısıldadı Van Helsing baş başa kaldıklarında Seward\'a ciddiyetle.', 'notes': 'ordinary medicine: sıradan tıp.'}, {'id': 199, 'text': '"The blood is being drawn from her body night after night by some terrible, unseen force."', 'translation': '"Korkunç ve görünmez bir güç tarafından gece ardına gece onun bedeninden kan çekiliyor."', 'notes': 'unseen force: görünmez güç.'}, {'id': 200, 'text': '"If we do not act with utmost vigilance, this lovely girl will perish before our very eyes!"', 'translation': '"Eğer son derece teyakkuzla hareket etmezsek, bu güzel kız gözlerimizin önünde can verecek!"', 'notes': 'utmost vigilance: azami dikkat/teyakkuz.'}]}, {'page_no': 11, 'title': "The Garland of Garlic and the Life's Blood", 'tr_title': 'Sarımsak Çelengi ve Can Veren Kan', 'vocab_focus': [('transfusion', 'kan nakli'), ('pungent', 'keskin kokulu'), ('garlic', 'sarımsak'), ('wreath', 'çelenk'), ('vein', 'damar'), ('vigor', 'dinçlik, canlılık'), ('supernatural', 'doğaüstü'), ('reassurance', 'güvence, teselli')], 'sentences': [{'id': 201, 'text': 'The next morning, Lucy sank into a profound coma, her pulse beating so feebly that it was barely perceptible.', 'translation': 'Ertesi sabah Lucy derin bir komaya girdi; nabzı o kadar zayıf atıyordu ki neredeyse hissedilmiyordu.', 'notes': 'profound coma: derin koma.'}, {'id': 202, 'text': '"There is only one hope to save her life: an immediate blood transfusion!" Van Helsing declared urgently.', 'translation': '"Hayatını kurtarmak için tek bir umut var: acil bir kan nakli!" diye ilan etti Van Helsing aciliyetle.', 'notes': 'immediate transfusion: acil kan nakli.'}, {'id': 203, 'text': "Arthur Holmwood stepped forward bravely, offering his own healthy veins without a moment's hesitation.", 'translation': 'Arthur Holmwood bir an bile tereddüt etmeden kendi sağlıklı damarlarını sunarak cesurca öne çıktı.', 'notes': 'without hesitation: tereddüt etmeden.'}, {'id': 204, 'text': "Van Helsing connected their arms with rubber tubes and pumped Arthur's vigorous blood into Lucy's failing heart.", 'translation': "Van Helsing kollarını kauçuk tüplerle birbirine bağladı ve Arthur'un dinç kanını Lucy'nin tekleyen kalbine pompaladı.", 'notes': 'failing heart: tekleyen/zayıflayan kalp.'}, {'id': 205, 'text': "Within minutes, a miracle occurred; color returned to Lucy's pale lips, and she opened her eyes with a smile.", 'translation': "Birkaç dakika içinde bir mucize gerçekleşti; Lucy'nin solgun dudaklarına renk geldi ve bir gülümsemeyle gözlerini açtı.", 'notes': 'miracle occurred: mucize gerçekleşti.'}, {'id': 206, 'text': 'The following day, Van Helsing received a wooden crate sent by express delivery from a colleague in Amsterdam.', 'translation': "Ertesi gün Van Helsing Amsterdam'daki bir meslektaşından acele kargoyla gönderilen tahta bir sandık aldı.", 'notes': 'express delivery: hızlı teslimat/kargo.'}, {'id': 207, 'text': 'Inside the crate was a massive bundle of white garlic flowers, filling the room with a pungent herbal odor.', 'translation': 'Sandığın içinde odayı keskin bir bitki kokusuyla dolduran koca bir deste beyaz sarımsak çiçeği vardı.', 'notes': 'pungent herbal odor: keskin bitkisel koku.'}, {'id': 208, 'text': "Van Helsing rubbed the crushed blossoms along the sash and sills of every window in Lucy's bedroom.", 'translation': "Van Helsing ezilmiş çiçekleri Lucy'nin yatak odasındaki her pencerenin çerçevesine ve eşiğine sürdü.", 'notes': 'crushed blossoms: ezilmiş çiçekler.'}, {'id': 209, 'text': "He then wove a necklace of garlic flowers and fastened it securely around Lucy's delicate neck.", 'translation': "Ardından sarımsak çiçeklerinden bir kolye ördü ve onu Lucy'nin narin boynuna sıkıca bağladı.", 'notes': 'wove a necklace: kolye ördü.'}, {'id': 210, 'text': '"Promise me, dear child, that you will never remove this garland, no matter what happens," the professor pleaded.', 'translation': '"Bana söz ver sevgili yavrum, ne olursa olsun bu çelengi asla çıkarmayacaksın," diye yalvardı profesör.', 'notes': 'pleaded solemnly: ciddiyetle yalvardı.'}, {'id': 211, 'text': 'That night, Lucy slept peacefully without nightmares, and her strength continued to improve steadily.', 'translation': 'O gece Lucy kabus görmeden huzurla uyudu ve gücü istikrarlı bir şekilde düzelmeye devam etti.', 'notes': 'slept peacefully: huzurla uyudu.'}, {'id': 212, 'text': "However, the following evening, Lucy's mother, Mrs. Westenra, entered the bedroom to check on her daughter.", 'translation': "Fakat ertesi akşam Lucy'nin annesi Bayan Westenra kızını kontrol etmek için yatak odasına girdi.", 'notes': 'check on daughter: kızını kontrol etmek.'}, {'id': 213, 'text': 'Finding the heavy garlic stench unbearable, the well-meaning mother opened the window and threw the flowers away.', 'translation': 'Ağır sarımsak kokusunu dayanılmaz bulan iyi niyetli anne pencereyi açtı ve çiçekleri çöpe attı.', 'notes': 'well-meaning mother: iyi niyetli anne.'}, {'id': 214, 'text': 'When Van Helsing and Seward arrived at sunrise, they discovered Lucy once again on the brink of death.', 'translation': "Gündoğumunda Van Helsing ve Seward geldiklerinde Lucy'yi bir kez daha ölümün eşiğinde buldular.", 'notes': 'brink of death: ölümün eşiği.'}, {'id': 215, 'text': 'The puncture marks on her neck had been reopened, and her blood had been drained almost completely.', 'translation': 'Boynundaki delik yaraları yeniden açılmış ve kanı neredeyse tamamen emilmişti.', 'notes': 'drained completely: tamamen boşaltılmış/emilmiş.'}, {'id': 216, 'text': 'Without hesitation, Dr. John Seward volunteered his own blood, and a second life-saving transfusion was performed.', 'translation': 'Doktor John Seward hiç tereddüt etmeden kendi kanını bağışladı ve hayat kurtaran ikinci bir nakil gerçekleştirildi.', 'notes': 'second transfusion: ikinci nakil.'}, {'id': 217, 'text': 'Two days later, another mysterious nocturnal attack occurred, requiring a third transfusion from Quincey Morris.', 'translation': "İki gün sonra esrarengiz bir gece saldırısı daha gerçekleşti ve Quincey Morris'ten üçüncü bir nakil yapılması gerekti.", 'notes': 'nocturnal attack: gece saldırısı.'}, {'id': 218, 'text': '"Four strong men have poured their lifeblood into this girl, yet she starves for blood!" Seward cried in agony.', 'translation': '"Dört güçlü adam can damarlarındaki kanı bu kıza akıttı ama o yine de kana muhtaç!" diye feryat etti Seward ızdırapla.', 'notes': 'cried in agony: ızdırapla haykırdı.'}, {'id': 219, 'text': 'Van Helsing explained that an ancient, supernatural vampire was stalking Lucy, defying all conventional laws of nature.', 'translation': "Van Helsing doğanın tüm alışılagelmiş yasalarına meydan okuyan kadim, doğaüstü bir vampirin Lucy'nin peşinde olduğunu açıkladı.", 'notes': 'defying laws of nature: doğa kanunlarına meydan okuyan.'}, {'id': 220, 'text': 'The defenders redoubled their watch, but a catastrophe beyond their imagination was already descending upon the house.', 'translation': 'Savunucular nöbetlerini iki katına çıkardılar ancak hayal güçlerinin ötesinde bir felaket çoktan evin üzerine çökmekteydi.', 'notes': 'descending upon house: evin üzerine çöken.'}]}, {'page_no': 12, 'title': "The Escaped Wolf and Lucy's Tragic End", 'tr_title': "Kaçan Kurt ve Lucy'nin Trajik Sonu", 'vocab_focus': [('berserk', 'çılgına dönmüş, gözü dönmüş'), ('shatter', 'paramparça etmek'), ('suffocation', 'boğulma'), ('funeral', 'cenaze töreni'), ('unearthly', 'tekinsiz, dünya dışı'), ('radiance', 'ışıltı, parlaklık'), ('canine', 'köpek dişi'), ('mausoleum', 'anıt mezar, türbe')], 'sentences': [{'id': 221, 'text': 'That same afternoon, a massive grey wolf escaped from its enclosure at the London Zoological Gardens.', 'translation': "Aynı öğleden sonra Londra Zooloji Bahçeleri'ndeki kafesinden devasa gri bir kurt kaçtı.", 'notes': 'escaped from enclosure: kafesinden kaçtı.'}, {'id': 222, 'text': 'The zookeeper reported that a tall nobleman with flashing eyes had spoken softly to the beast through the bars.', 'translation': 'Hayvanat bahçesi bakıcısı, parıldayan gözlü uzun boylu bir soylunun parmaklıklar ardından canavarla usulca konuştuğunu bildirdi.', 'notes': 'flashing eyes: parıldayan gözler.'}, {'id': 223, 'text': "Late that night, while Mrs. Westenra sat beside Lucy's bed, a dreadful scratching sounded outside the window.", 'translation': "O gece geç saatlerde Bayan Westenra Lucy'nin yatağının yanında otururken pencerenin dışından korkunç bir tırmalama sesi geldi.", 'notes': 'scratching sounded: tırmalama sesi duyuldu.'}, {'id': 224, 'text': 'Suddenly, the enormous wolf smashed through the glass panes in a shower of sharp fragments!', 'translation': 'Ansızın, devasa kurt keskin cam kırıkları yağmuru eşliğinde cam bölmeleri kırıp içeri daldı!', 'notes': 'smashed through: kırıp geçti.'}, {'id': 225, 'text': 'Terrified by the ferocious beast, Mrs. Westenra suffered a massive heart attack and collapsed dead across the bed.', 'translation': 'Vahşi canavardan dehşete düşen Bayan Westenra ağır bir kalp krizi geçirdi ve yatağın üzerine cansız yığıldı.', 'notes': 'massive heart attack: ağır kalp krizi.'}, {'id': 226, 'text': "As she fell, the dying mother accidentally tore the garland of garlic flowers from Lucy's neck.", 'translation': "Ölmekte olan anne yere düşerken kazara sarımsak çiçeği çelengini Lucy'nin boynundan çekip kopardı.", 'notes': 'tore the garland: çelengi yırttı/kopardı.'}, {'id': 227, 'text': "A thick, unnatural grey mist poured through the shattered window, swirling around Lucy's defenseless form.", 'translation': "Kırık pencereden içeri kalın, tekinsiz gri bir sis doldu ve Lucy'nin savunmasız bedeninin etrafında girdap gibi döndü.", 'notes': 'unnatural grey mist: tekinsiz gri sis.'}, {'id': 228, 'text': 'The next morning, Van Helsing and Seward arrived to find Mrs. Westenra dead and Lucy sinking rapidly into death.', 'translation': "Ertesi sabah Van Helsing ve Seward geldiklerinde Bayan Westenra'yı ölü, Lucy'yi ise hızla ölüme sürüklenirken buldular.", 'notes': 'sinking rapidly: hızla batan/sürüklenen.'}, {'id': 229, 'text': 'Van Helsing summoned Arthur Holmwood, but warned him that medical science had reached its ultimate limits.', 'translation': "Van Helsing Arthur Holmwood'u çağırdı ancak tıp biliminin nihai sınırlarına ulaştığı konusunda onu uyardı.", 'notes': 'ultimate limits: nihai sınırlar.'}, {'id': 230, 'text': 'As Arthur entered the room weeping, Lucy opened her eyes, but her expression was horrifyingly altered.', 'translation': 'Arthur gözyaşları içinde odaya girdiğinde Lucy gözlerini açtı fakat yüz ifadesi korkunç bir şekilde değişmişti.', 'notes': 'horrifyingly altered: korkunç şekilde değişmiş.'}, {'id': 231, 'text': 'Her pointed canine teeth were unnaturally long, and her voice possessed a wicked, sensual whisper.', 'translation': 'Sivri köpek dişleri doğal olmayan şekilde uzundu ve sesi şeytani, şehvetli bir fısıltı taşıyordu.', 'notes': 'wicked sensual whisper: şeytani şehvetli fısıltı.'}, {'id': 232, 'text': '"Arthur, my love, kiss me! Kiss me on the lips!" she whispered with hungry, gleaming eyes.', 'translation': '"Arthur sevgilim, öp beni! Dudaklarımdan öp beni!" diye fısıldadı aç, parıldayan gözlerle.', 'notes': 'kiss on the lips: dudaklarından öpmek.'}, {'id': 233, 'text': 'Enchanted by her beauty, Arthur leaned forward to embrace her, but Van Helsing hurled him backward with astonishing strength.', 'translation': 'Güzelliğiyle büyülenen Arthur ona sarılmak için öne eğildi fakat Van Helsing şaşırtıcı bir güçle onu geriye savurdu.', 'notes': 'hurled backward: geriye savurdu.'}, {'id': 234, 'text': '"Do not touch her lips for your very soul\'s sake!" the professor shouted fiercely.', 'translation': '"Ruhunun selameti için onun dudaklarına sakın dokunma!" diye şiddetle bağırdı profesör.', 'notes': "for your soul's sake: ruhunun hatırına/selameti için."}, {'id': 235, 'text': 'Deprived of her prey, Lucy uttered a snarling hiss, closed her eyes, and died peacefully a few moments later.', 'translation': 'Avından mahrum kalan Lucy hırlayan bir tıslama koyverdi, gözlerini kapadı ve birkaç dakika sonra huzurla öldü.', 'notes': 'snarling hiss: hırlayan bir tıslama.'}, {'id': 236, 'text': 'A holy look of serenity settled upon her features, and the sharp pointedness of her teeth seemed to vanish.', 'translation': 'Yüz hatlarına kutsal bir huzur ifadesi yerleşti ve dişlerinin sivri sivriliği kaybolur gibi oldu.', 'notes': 'serenity: dinginlik, huzur.'}, {'id': 237, 'text': 'Yet when Van Helsing examined the corpse the following morning, he observed a terrifying phenomenon.', 'translation': 'Fakat Van Helsing ertesi sabah cesedi muayene ettiğinde korkunç bir doğa olayına tanık oldu.', 'notes': 'terrifying phenomenon: korkunç olgu/olay.'}, {'id': 238, 'text': 'Lucy did not exhibit the slightest signs of decomposition; instead, her skin was radiant and her lips ruby-red.', 'translation': 'Lucy en ufak bir çürüme belirtisi göstermiyordu; aksine teni ışıl ışıldı ve dudakları yakut kırmızısıydı.', 'notes': 'signs of decomposition: çürüme belirtileri.'}, {'id': 239, 'text': 'She looked more alluring and breathtakingly beautiful in death than she had ever appeared in life.', 'translation': 'Ölümünde, hayatta göründüğünden çok daha çekici ve nefes kesici derecede güzel görünüyordu.', 'notes': 'alluring: çekici, cazibeli.'}, {'id': 240, 'text': 'Lucy was laid to rest beside her ancestors in the grand Westenra family mausoleum in a churchyard near Hampstead.', 'translation': 'Lucy Hampstead yakınlarındaki bir mezarlıkta görkemli Westenra aile anıt mezarında atalarının yanına defnedildi.', 'notes': 'laid to rest: toprağa verildi, defnedildi.'}]}, {'page_no': 13, 'title': 'The Bloofer Lady and the Empty Tomb', 'tr_title': 'Güzel Hanım ve Boş Mezar', 'vocab_focus': [('toddler', 'yürümeye yeni başlayan çocuk'), ('heath', 'fundalık, kır'), ('abduction', 'kaçırma'), ('crypt', 'mahzen mezar'), ('coffin', 'tabut'), ('screw', 'vida'), ('sacrilege', 'kutsala saygısızlık'), ('proof', 'kanıt, delil')], 'sentences': [{'id': 241, 'text': "A week after Lucy's funeral, disturbing reports began appearing in the local London newspapers.", 'translation': "Lucy'nin cenazesinden bir hafta sonra yerel Londra gazetelerinde rahatsız edici haberler çıkmaya başladı.", 'notes': 'disturbing reports: rahatsız edici haberler.'}, {'id': 242, 'text': 'Several young children had vanished while playing near Hampstead Heath during twilight hours.', 'translation': 'Alacakaranlık saatlerinde Hampstead Fundalığı yakınlarında oynayan birkaç küçük çocuk kaybolmuştu.', 'notes': 'vanished while playing: oynarken kayboldu.'}, {'id': 243, 'text': 'Each missing toddler was discovered the following morning, unharmed but weak, sleeping among the ferns.', 'translation': 'Kayıp her çocuk ertesi sabah eğrelti otlarının arasında uyurken zarar görmemiş fakat halsiz halde bulundu.', 'notes': 'sleeping among ferns: eğrelti otları arasında uyuyan.'}, {'id': 244, 'text': "Upon every child's throat were two tiny red marks, identical to the punctures that had afflicted Lucy.", 'translation': "Her çocuğun boğazında, Lucy'yi perişan eden deliklerle tıpatıp aynı iki küçük kırmızı iz vardı.", 'notes': 'identical punctures: tıpatıp aynı delikler.'}, {'id': 245, 'text': 'The children innocently explained that they had been playing in the woods with a "bloofer lady."', 'translation': 'Çocuklar masumca ormanda "güzel bir hanım" ile oynadıklarını anlattılar.', 'notes': 'bloofer lady: güzel hanım (çocuk diliyle beautiful lady).'}, {'id': 246, 'text': 'Reading these reports, Van Helsing called Dr. Seward and commanded him to bring his surgical instruments.', 'translation': "Bu haberleri okuyan Van Helsing Doktor Seward'ı aradı ve cerrahi aletlerini getirmesini emretti.", 'notes': 'surgical instruments: cerrahi aletler.'}, {'id': 247, 'text': '"We must visit the churchyard tonight, John, and open Lucy\'s tomb," Van Helsing declared somberly.', 'translation': '"Bu gece mezarlığı ziyaret etmeli ve Lucy\'nin kabrini açmalıyız John," dedi Van Helsing ağırbaşlılıkla.', 'notes': 'declared somberly: ağırbaşlılıkla ilan etti.'}, {'id': 248, 'text': 'Seward was horrified, protesting that desecrating the grave of their beloved friend was a monstrous sacrilege.', 'translation': 'Seward çok sevdikleri dostlarının mezarına saygısızlık etmenin canavarca bir günah olduğunu savunarak dehşete kapıldı.', 'notes': 'monstrous sacrilege: canavarca kutsala saygısızlık/günah.'}, {'id': 249, 'text': '"You shall see with your own eyes that she is not there," the Dutch professor replied with unwavering certainty.', 'translation': '"Onun orada olmadığını kendi gözlerinle göreceksin," diye yanıtladı Hollandalı profesör sarsılmaz bir kesinlikle.', 'notes': 'unwavering certainty: sarsılmaz kesinlik.'}, {'id': 250, 'text': 'At midnight, they entered the silent Hampstead cemetery, unlocked the heavy iron door of the mausoleum, and descended.', 'translation': 'Gece yarısı sessiz Hampstead mezarlığına girdiler, anıt mezarın ağır demir kapısını açtılar ve aşağı indiler.', 'notes': 'descended: aşağı indiler.'}, {'id': 251, 'text': "Using a screwdriver, Van Helsing carefully removed the screws from Lucy's heavy lead coffin.", 'translation': "Bir tornavida kullanan Van Helsing Lucy'nin ağır kurşun tabutunun vidalarını dikkatlice söktü.", 'notes': 'heavy lead coffin: ağır kurşun tabut.'}, {'id': 252, 'text': 'When the lid was lifted, Seward gasped in utter astonishment: the satin interior was completely empty!', 'translation': 'Kapak kaldırıldığında Seward büyük bir şaşkınlıkla nefesini tuttu: Saten iç kısım bomboştu!', 'notes': 'gasped in astonishment: şaşkınlıkla nefesi kesildi.'}, {'id': 253, 'text': '"Could someone have stolen the body?" Seward whispered, trembling in the cold crypt.', 'translation': '"Biri cesedi çalmış olabilir mi?" diye fısıldadı Seward soğuk mahzende titreyerek.', 'notes': 'stolen the body: cesedi çalmış.'}, {'id': 254, 'text': '"No human thief has touched this coffin; she walks among us as an Un-Dead predator!" Van Helsing answered.', 'translation': '"Bu tabuta hiçbir insan hırsız dokunmadı; o yaşayan bir ölü, bir avcı olarak aramızda dolaşıyor!" diye yanıtladı Van Helsing.', 'notes': 'Un-Dead predator: yaşayan ölü/hortlak avcı.'}, {'id': 255, 'text': 'They concealed themselves behind a marble tombstone outside the mausoleum to keep watch through the night.', 'translation': 'Gece boyunca nöbet tutmak için anıt mezarın dışındaki mermer bir mezar taşının arkasına gizlendiler.', 'notes': 'keep watch: nöbet tutmak.'}, {'id': 256, 'text': "Near three o'clock, a luminous white figure glided gracefully between the yew trees toward the tomb.", 'translation': 'Saat üçe doğru ışık saçan beyaz bir siluet porsuk ağaçlarının arasından kabre doğru zarifçe süzüldü.', 'notes': 'luminous white figure: ışıldayan beyaz siluet.'}, {'id': 257, 'text': 'It was Lucy Westenra, dressed in her burial shroud, clutching a whimpering young child to her breast.', 'translation': "Kefenine bürünmüş, inleyen küçük bir çocuğu göğsüne bastıran kişi Lucy Westenra'ydı.", 'notes': 'burial shroud: kefen.'}, {'id': 258, 'text': 'Her lips were smeared with fresh blood, and her eyes burned with cruel, predatory lust.', 'translation': 'Dudakları taze kanla sıvanmıştı ve gözleri zalim, yırtıcı bir şehvetle parıldıyordu.', 'notes': 'predatory lust: yırtıcı şehvet.'}, {'id': 259, 'text': 'When Van Helsing stepped forward holding a crucifix, she snarled like a rabid beast and dropped the child onto the grass.', 'translation': 'Van Helsing elinde bir haç tutarak öne çıktığında Lucy kuduz bir canavar gibi hırladı ve çocuğu çimlerin üzerine fırlattı.', 'notes': 'rabid beast: kuduz canavar.'}, {'id': 260, 'text': 'Before they could seize her, she dematerialized into a white vapor and slipped through the sealed door of the tomb.', 'translation': 'Onlar onu yakalayamadan beyaz bir buhara dönüştü ve mezarın mühürlü kapısının arasından içeri süzüldü.', 'notes': 'dematerialized into vapor: buhara dönüştü/eridi.'}]}, {'page_no': 14, 'title': 'The Stake of Oak and Eternal Rest', 'tr_title': 'Meşe Kazık ve Ebedi Huzur', 'vocab_focus': [('stake', 'kazık'), ('mallet', 'tokmak'), ('undead', 'hortlak, ölümsüz'), ('hiss', 'tıslamak'), ('consecration', 'kutsama'), ('decapitate', 'başını kesmek'), ('garlic', 'sarımsak'), ('peaceful', 'huzurlu')], 'sentences': [{'id': 261, 'text': 'The next day, Van Helsing summoned Arthur Holmwood and Quincey Morris to join them at the cemetery.', 'translation': "Ertesi gün Van Helsing Arthur Holmwood ve Quincey Morris'i mezarlıkta kendilerine katılmaları için çağırdı.", 'notes': 'summoned to join: katılmaları için çağırdı.'}, {'id': 262, 'text': 'Arthur was indignant, refusing to believe that his pure, gentle fiancée could be anything evil.', 'translation': 'Saf ve narin nişanlısının kötü bir şey olabileceğine inanmayı reddeden Arthur öfke doluydu.', 'notes': 'indignant: öfkeli, gücenmiş.'}, {'id': 263, 'text': '"Come and see with your own eyes, Lord Godalming," Van Helsing said gently; "then judge if I speak true."', 'translation': '"Kendi gözlerinizle gelin ve görün Lord Godalming," dedi Van Helsing nazikçe; "o zaman doğru söyleyip söylemediğime karar verin."', 'notes': 'judge if I speak true: doğru söyleyip söylemediğime karar verin.'}, {'id': 264, 'text': 'They descended into the tomb and unsealed the coffin, revealing Lucy lying inside in supernatural radiance.', 'translation': "Kabrin içine indiler ve tabutu açtılar; Lucy'nin doğaüstü bir ışıltı içinde yattığını gördüler.", 'notes': 'supernatural radiance: doğaüstü ışıltı.'}, {'id': 265, 'text': 'Her cheeks were flushed crimson, her lips plump with stolen blood, and her long white fangs bared in a cruel smirk.', 'translation': 'Yanakları al al parlıyordu, dudakları çalınmış kanla dolgundu ve uzun beyaz dişleri zalim bir sırıtışla açığa çıkmıştı.', 'notes': 'cruel smirk: zalim bir sırıtış.'}, {'id': 266, 'text': 'Arthur broke down in tears of agony, recognizing the terrifying reality of what his beloved had become.', 'translation': 'Arthur sevgilisinin neye dönüştüğünün korkunç gerçeğini anlayarak ızdırap gözyaşlarıyla yıkıldı.', 'notes': 'broke down in tears: gözyaşlarına boğuldu.'}, {'id': 267, 'text': '"She is no longer the Lucy you loved," Van Helsing explained with solemn compassion.', 'translation': '"O artık sizin sevdiğiniz Lucy değil," diye açıkladı Van Helsing vakur bir şefkatle.', 'notes': 'solemn compassion: vakur şefkat.'}, {'id': 268, 'text': '"She is a demon wearing her earthly shell, preying on little children and doomed to eternal damnation."', 'translation': '"O küçük çocukları avlayan ve ebedi lanete mahkûm olan, onun dünyevi kabuğuna bürünmüş bir iblistir."', 'notes': 'eternal damnation: ebedi lanet.'}, {'id': 269, 'text': '"To set her soul free and restore her to heaven, we must perform a sacred, agonizing duty."', 'translation': '"Ruhunu özgür kılmak ve onu cennete kavuşturmak için kutsal ve kahredici bir görevi yerine getirmeliyiz."', 'notes': 'agonizing duty: kahredici görev.'}, {'id': 270, 'text': 'Van Helsing produced a sharpened oak stake three feet long and a heavy iron mallet from his bag.', 'translation': 'Van Helsing çantasından üç fit uzunluğunda sivri uçlu bir meşe kazık ve ağır bir demir tokmak çıkardı.', 'notes': 'sharpened oak stake: sivriltilmiş meşe kazık.'}, {'id': 271, 'text': '"Arthur, it is your rightful privilege to deliver the blow that frees the soul of your bride," Van Helsing said.', 'translation': '"Arthur, gelininin ruhunu özgür kılacak darbeyi indirmek senin en doğal hakkındır," dedi Van Helsing.', 'notes': 'rightful privilege: en doğal hak/ayrıcalık.'}, {'id': 272, 'text': "Steeling his courage with trembling resolve, Arthur took the mallet and placed the point of the stake over Lucy's heart.", 'translation': "Titreyen kararlılığıyla cesaretini toplayan Arthur tokmağı aldı ve kazığın ucunu Lucy'nin kalbinin üzerine yerleştirdi.", 'notes': 'steeling his courage: cesaretini toplayarak.'}, {'id': 273, 'text': 'Van Helsing opened his Latin prayer book and began reading the solemn office for the dead.', 'translation': 'Van Helsing Latince dua kitabını açtı ve ölüler için okunan kutsal duaları okumaya başladı.', 'notes': 'office for the dead: ölüler duası/ayin.'}, {'id': 274, 'text': 'With a desperate cry of grief and love, Arthur struck the stake with all his physical might!', 'translation': 'Keder ve aşk dolu çaresiz bir haykırışla Arthur bütün fiziksel gücüyle kazığa vurdu!', 'notes': 'physical might: fiziksel güç.'}, {'id': 275, 'text': 'The corpse convulsed violently, screeching in horrifying agony while red blood gushed around the driving wood.', 'translation': 'Ceset şiddetle kasıldı, korkunç bir acıyla çığlık attı; bu sırada saplanan tahtanın etrafından kızıl kan fışkırdı.', 'notes': 'convulsed violently: şiddetle kasıldı.'}, {'id': 276, 'text': 'Arthur struck again and again until the stake drove completely through the heart into the wood below.', 'translation': 'Arthur kazık kalbi tamamen delip aşağıdaki ahşaba saplanana kadar tekrar tekrar vurdu.', 'notes': 'struck again and again: tekrar tekrar vurdu.'}, {'id': 277, 'text': "Gradually, the terrible writhing ceased, and a look of divine peace transformed Lucy's pale countenance.", 'translation': "Giderek o korkunç çırpınma durdu ve ilahi bir barış ifadesi Lucy'nin solgun çehresini güzelleştirdi.", 'notes': 'divine peace: ilahi barış/huzur.'}, {'id': 278, 'text': 'The twisted demon was gone; before them lay their pure, innocent friend sleeping the peaceful sleep of heaven.', 'translation': 'O çarpık iblis gitmişti; karşılarında masum dostları cennetin huzurlu uykusunu uyur halde yatıyordu.', 'notes': 'peaceful sleep: huzurlu uyku.'}, {'id': 279, 'text': 'To complete the ritual, they severed the head, filled the mouth with garlic, and soldered the coffin closed forever.', 'translation': 'Ritüeli tamamlamak için başını kestiler, ağzını sarımsakla doldurdular ve tabutu sonsuza dek lehimleyerek kapattılar.', 'notes': 'severed the head: başını kestiler.'}, {'id': 280, 'text': '"Now Lucy is at peace," Van Helsing said softly, "and now our holy war against her murderer begins!"', 'translation': '"Artık Lucy huzur içinde," dedi Van Helsing usulca, "ve şimdi onun katiline karşı kutsal savaşımız başlıyor!"', 'notes': 'holy war: kutsal savaş.'}]}, {'page_no': 15, 'title': 'The Alliance of the Five Hunters', 'tr_title': 'Beş Avcının İttifakı', 'vocab_focus': [('convalescence', 'nekahat, iyileşme dönemi'), ('transcribe', 'yazıya dökmek, temize çekmek'), ('journal', 'günlük'), ('shorthand', 'steno'), ('typewriter', 'daktilo'), ('collaborate', 'işbirliği yapmak'), ('crusade', 'kutsal savaş, haçlı seferi'), ('tactics', 'taktikler')], 'sentences': [{'id': 281, 'text': "Shortly after Lucy's soul was freed, Jonathan and Mina Harker returned to London from Budapest.", 'translation': "Lucy'nin ruhu kurtarıldıktan kısa bir süre sonra Jonathan ve Mina Harker Budapeşte'den Londra'ya döndüler.", 'notes': "returned from Budapest: Budapeşte'den döndü."}, {'id': 282, 'text': "They had married in the hospital chapel during Jonathan's convalescence, their love deepened by adversity.", 'translation': "Jonathan'ın iyileşme sürecinde hastane şapelinde evlenmişlerdi; zorluklar aşklarını daha da pekiştirmişti.", 'notes': 'deepened by adversity: zorluklarla pekişen.'}, {'id': 283, 'text': "Jonathan's hair had turned prematurely silver, and he was tormented by doubts regarding his Transylvanian ordeal.", 'translation': "Jonathan'ın saçları vaktinden önce gümüşleşmişti ve Transilvanya'da yaşadığı çileye dair şüphelerle kıvranıyordu.", 'notes': 'prematurely silver: vaktinden önce beyazlayan.'}, {'id': 284, 'text': "Mina delivered Jonathan's private shorthand journal to Professor Van Helsing, hoping the wise scholar could interpret it.", 'translation': "Mina bilge alimin bunu yorumlayabileceğini umarak Jonathan'ın özel steno günlüğünü Profesör Van Helsing'e teslim etti.", 'notes': 'interpret shorthand journal: steno günlüğü yorumlamak.'}, {'id': 285, 'text': "Van Helsing read the diary through the night with mounting amazement and profound admiration for Harker's bravery.", 'translation': "Van Helsing günlüğü gece boyunca artan bir şaşkınlıkla ve Harker'ın cesaretine derin bir hayranlıkla okudu.", 'notes': 'mounting amazement: giderek artan şaşkınlık.'}, {'id': 286, 'text': '"Every single word in this journal is true!" Van Helsing exclaimed warmly, grasping Jonathan\'s hands.', 'translation': '"Bu günlükteki her bir kelime harfiyen doğrudur!" diye haykırdı Van Helsing içtenlikle Jonathan\'ın ellerini sıkarak.', 'notes': 'grasping hands: elleri kavrayarak.'}, {'id': 287, 'text': '"You are not mad, my brave friend; you survived the lair of the king of vampires himself!"', 'translation': '"Sen deli değilsin cesur dostum; sen bizzat vampirler kralının ininden sağ çıktın!"', 'notes': 'king of vampires: vampirler kralı.'}, {'id': 288, 'text': "This validation restored Jonathan's self-confidence and vigor, curing the lingering shadows of his fever.", 'translation': "Bu doğrulama Jonathan'ın özgüvenini ve dinçliğini geri getirdi; hummasının kalıcı gölgelerini iyileştirdi.", 'notes': 'restored self-confidence: özgüveni tazeledi.'}, {'id': 289, 'text': "Van Helsing gathered their entire company at Dr. Seward's asylum to organize their plan of campaign.", 'translation': "Van Helsing sefer planlarını organize etmek için bütün ekibi Doktor Seward'ın akıl hastanesinde topladı.", 'notes': 'plan of campaign: sefer/harekât planı.'}, {'id': 290, 'text': 'The five comrades in arms were Van Helsing, Dr. Seward, Arthur Holmwood, Quincey Morris, and Jonathan Harker.', 'translation': "Silah arkadaşı olan beş yoldaş Van Helsing, Doktor Seward, Arthur Holmwood, Quincey Morris ve Jonathan Harker'dı.", 'notes': 'comrades in arms: silah arkadaşları.'}, {'id': 291, 'text': 'Mina Harker became their chief intelligence officer, using her typewriter and organizational skills.', 'translation': 'Mina Harker daktilosunu ve teşkilatçılık becerilerini kullanarak onların baş istihbarat sorumlusu oldu.', 'notes': 'chief intelligence officer: baş istihbarat sorumlusu.'}, {'id': 292, 'text': 'She typed copies of all diaries, letters, telegrams, and newspaper clippings into a single chronological master file.', 'translation': 'Tüm günlükleri, mektupları, telgrafları ve gazete kupürlerini tek bir kronolojik ana dosyada daktiloyla temize çekti.', 'notes': 'chronological master file: kronolojik ana dosya.'}, {'id': 293, 'text': 'By examining the integrated evidence, the monstrous reality became crystal clear to everyone.', 'translation': 'Birleştirilmiş kanıtları inceleyerek o korkunç gerçek herkes için gün gibi aşikâr hale geldi.', 'notes': 'crystal clear: apaçık, gün gibi ortada.'}, {'id': 294, 'text': 'Count Dracula had traveled to England on the Demeter with fifty boxes of earth to establish a new empire of darkness.', 'translation': "Kont Drakula karanlığın yeni bir imparatorluğunu kurmak için elli sandık toprakla Demeter gemisinde İngiltere'ye gelmişti.", 'notes': 'empire of darkness: karanlık imparatorluğu.'}, {'id': 295, 'text': "He had seduced and murdered Lucy, and now roamed London's foggy streets in search of fresh victims.", 'translation': "Lucy'yi baştan çıkarıp katletmişti ve şimdi taze kurbanlar aramak için Londra'nın sisli sokaklarında cirit atıyordu.", 'notes': 'foggy streets: sisli sokaklar.'}, {'id': 296, 'text': '"We are dealing with a being of immense antiquity, superhuman strength, and cunning intellect," Van Helsing warned.', 'translation': '"Son derece kadim, insanüstü güce ve kurnaz bir zekaya sahip bir varlıkla karşı karşıyayız," diye uyardı Van Helsing.', 'notes': 'immense antiquity: muazzam kadimlik.'}, {'id': 297, 'text': '"He can transform into a wolf, a bat, or a drifting mist; he can command storms, rats, and wolves."', 'translation': '"Bir kurda, bir yarasaya veya süzülen bir sise dönüşebilir; fırtınalara, sıçanlara ve kurtlara hükmedebilir."', 'notes': 'drifting mist: sürüklenen sis.'}, {'id': 298, 'text': '"Yet he has limitations: he must sleep in his native earth, and he loses his supernatural powers in daylight."', 'translation': '"Fakat kısıtlamaları da vardır: Kendi vatan toprağında uyumalıdır ve gün ışığında doğaüstü güçlerini kaybeder."', 'notes': 'loses powers in daylight: gün ışığında güçlerini kaybeder.'}, {'id': 299, 'text': '"Our primary mission is to locate all fifty boxes of earth and sterilize them with holy consecrated wafers."', 'translation': '"Birincil görevimiz elli toprak sandığının hepsini bulmak ve onları kutsanmış ekmekle arındırmaktır."', 'notes': 'sterilize boxes: sandıkları arındırmak/etkisiz kılmak.'}, {'id': 300, 'text': "Placing their hands upon Van Helsing's crucifix, the five men swore a solemn oath to rid the world of the monster.", 'translation': "Ellerini Van Helsing'in haçı üzerine koyan beş adam, dünyayı bu canavardan kurtarmak için kutsal bir yemin ettiler.", 'notes': 'swore a solemn oath: kutsal bir ant içtiler.'}]}, {'page_no': 16, 'title': 'The Holy Raid on Carfax Abbey', 'tr_title': "Carfax Manastırı'na Kutsal Baskın", 'vocab_focus': [('estate', 'mülk, arazi'), ('chapel', 'şapel, küçük kilise'), ('stench', 'pis koku'), ('swarm', 'sürü, kaynaşma'), ('rat', 'sıçan, sıçan sürüsü'), ('terrier', 'av köpeği, terye'), ('wafer', 'kutsal ekmek'), ('sanctify', 'kutsamak')], 'sentences': [{'id': 301, 'text': "The hunters decided that their first target must be Carfax Abbey, the derelict estate directly adjoining Seward's asylum.", 'translation': "Avcılar ilk hedeflerinin doğrudan Seward'ın tımarhanesine komşu olan metruk mülk Carfax Manastırı olması gerektiğine karar verdiler.", 'notes': 'derelict estate: terk edilmiş/metruk mülk.'}, {'id': 302, 'text': 'Equipped with silver lanterns, wooden stakes, crucifixes, and consecrated holy wafers, the men set out after dark.', 'translation': 'Gümüş fenerler, tahta kazıklar, haçlar ve kutsanmış ekmeklerle donanan adamlar hava karardıktan sonra yola çıktılar.', 'notes': 'equipped with: ile donatılmış.'}, {'id': 303, 'text': 'They climbed over the crumbling stone wall separating the asylum grounds from the neglected wilderness of Carfax.', 'translation': "Tımarhane arazisini Carfax'ın bakımsız yabanlığından ayıran yıkık dökük taş duvarın üzerinden tırmandılar.", 'notes': 'neglected wilderness: bakımsız ıssızlık.'}, {'id': 304, 'text': 'The ancient mansion was surrounded by towering oak trees whose twisted branches clawed at the moonlit sky.', 'translation': 'Kadim konak, çarpık dalları mehtaplı gökyüzünü tırmalayan heybetli meşe ağaçlarıyla çevriliydi.', 'notes': 'twisted branches: çarpık dallar.'}, {'id': 305, 'text': "Jonathan used a set of locksmith tools to pick the heavy lock of the mansion's rear chapel door.", 'translation': 'Jonathan konağın arka şapel kapısının ağır kilidini açmak için bir çilingir alet takımı kullandı.', 'notes': 'locksmith tools: çilingir aletleri.'}, {'id': 306, 'text': 'As the door creaked open, an overwhelming stench of rotting corpses and damp earth billowed out into the night.', 'translation': 'Kapı gıcırdayarak açılırken çürüyen cesetlerin ve nemli toprağın boğucu pis kokusu gecenin içine dalga dalga yayıldı.', 'notes': 'overwhelming stench: boğucu pis koku.'}, {'id': 307, 'text': 'The men choked and held handkerchiefs to their faces, but Van Helsing urged them forward with determined resolve.', 'translation': 'Adamlar boğulur gibi oldu ve mendillerini yüzlerine tuttular fakat Van Helsing kararlı bir azimle onları ileri sürdü.', 'notes': 'determined resolve: kararlı azim.'}, {'id': 308, 'text': 'Inside the ruined chapel, moonlight poured through shattered stained-glass windows onto a scene of desolate ruin.', 'translation': 'Harap şapelin içinde ay ışığı, kırık vitray pencerelerden dökülerek ıssız bir harabe manzarasını aydınlatıyordu.', 'notes': 'stained-glass windows: vitray pencereler.'}, {'id': 309, 'text': 'Stacked in irregular piles against the damp stone walls were heavy wooden boxes filled with Transylvanian earth.', 'translation': 'Nemli taş duvarlara dayalı düzensiz yığınlar halinde Transilvanya toprağıyla dolu ağır tahta sandıklar duruyordu.', 'notes': 'irregular piles: düzensiz yığınlar.'}, {'id': 310, 'text': 'Jonathan counted the containers carefully and discovered there were only twenty-nine boxes in the chapel.', 'translation': 'Jonathan kutuları dikkatlice saydı ve şapelde yalnızca yirmi dokuz sandık olduğunu keşfetti.', 'notes': 'counted carefully: dikkatlice saydı.'}, {'id': 311, 'text': '"Twenty-one boxes have already been moved elsewhere in London!" Harker warned with deep frustration.', 'translation': '"Yirmi bir sandık çoktan Londra\'da başka bir yere taşınmış bile!" diye uyardı Harker derin bir hayal kırıklığıyla.', 'notes': 'deep frustration: derin hayal kırıklığı.'}, {'id': 312, 'text': 'Suddenly, a chilling scratching sound resonated from the dark subterranean recesses of the chapel floor.', 'translation': 'Ansızın, şapel zemininin karanlık yeraltı oyuklarından kan dondurucu bir tırmalama sesi yankılandı.', 'notes': 'subterranean recesses: yeraltı oyukları/girintileri.'}, {'id': 313, 'text': 'Within seconds, thousands of red-eyed rats poured from cracks in the stone floor, squealing in aggressive swarms.', 'translation': 'Saniyeler içinde, taş zemindeki çatlaklardan binlerce kırmızı gözlü sıçan fışkırdı; saldırgan sürüler halinde ciyaklıyorlardı.', 'notes': 'aggressive swarms: saldırgan sürüler.'}, {'id': 314, 'text': "The vile rodents surged across the floor, snapping at the men's boots and leaping toward their throats.", 'translation': 'Aşağılık kemirgenler adamların çizmelerine saldırarak ve boğazlarına doğru sıçrayarak zeminde dalgalandı.', 'notes': 'vile rodents: aşağılık kemirgenler.'}, {'id': 315, 'text': 'Quincey Morris immediately produced a brass whistle and blew a sharp, piercing blast into the courtyard.', 'translation': 'Quincey Morris derhal pirinç bir düdük çıkardı ve avluya doğru keskin, delici bir ses üfledi.', 'notes': 'piercing blast: delici düdük sesi.'}, {'id': 316, 'text': 'Three fierce fox-terriers rushed through the door, barking furiously and tearing into the rodent horde.', 'translation': 'Üç yırtıcı tilki teryesi öfkeyle havlayarak ve kemirgen sürüsünü parçalayarak kapıdan içeri daldı.', 'notes': 'fox-terriers: tilki teryeleri (av köpeği).'}, {'id': 317, 'text': 'Within minutes, the brave dogs slaughtered dozens of rats, driving the remaining horde back into the drains.', 'translation': 'Birkaç dakika içinde cesur köpekler onlarca sıçanı telef ederek kalan sürüyü lağımlara geri püskürttü.', 'notes': 'slaughtered dozens: onlarcasını telef etti.'}, {'id': 318, 'text': 'With the vermin dispersed, Van Helsing approached each of the twenty-nine wooden boxes with solemn reverence.', 'translation': 'Zararlılar dağıldıktan sonra Van Helsing vakur bir hürmetle yirmi dokuz ahşap sandığın her birine yaklaştı.', 'notes': 'solemn reverence: vakur hürmet.'}, {'id': 319, 'text': 'He pried open each lid, placed a portion of consecrated Host upon the soil, and sealed the box with holy water.', 'translation': 'Her kapağı kanırtarak açtı, toprağın üzerine kutsanmış ekmekten bir parça koydu ve sandığı kutsal suyla mühürledi.', 'notes': 'consecrated Host: kutsanmış ekmek/evharistiya.'}, {'id': 320, 'text': 'The consecrated earth was rendered spiritually pure, forever denying Dracula a resting place within Carfax Abbey.', 'translation': "Kutsanan toprak ruhani olarak arındırıldı ve Drakula'ya Carfax Manastırı içinde bir dinlenme yeri sonsuza dek men edildi.", 'notes': 'denying a resting place: dinlenme yerini men etmek.'}]}, {'page_no': 17, 'title': "Renfield's Sacrifice and the Midnight Intruder", 'tr_title': "Renfield'nin Fedakarlığı ve Gece Yarısı Davetsizi", 'vocab_focus': [('paralysis', 'felç'), ('fractured', 'kırılmış, çatlamış'), ('confession', 'itiraf'), ('lucid', 'berrak, aklı başında'), ('intruder', 'davetsiz misafir, zorla giren'), ('vapor', 'buhar, pus'), ('hallway', 'koridor, hol'), ('ward', 'koğuş, hasta odası')], 'sentences': [{'id': 321, 'text': 'Upon returning to the asylum after the raid on Carfax, the hunters were met with frantic emergency.', 'translation': 'Carfax baskınından sonra akıl hastanesine dönen avcılar telaşlı bir acil durumla karşılaştılar.', 'notes': 'frantic emergency: telaşlı acil durum.'}, {'id': 322, 'text': 'An attendant rushed forward, announcing that Renfield had suffered a terrible and mysterious accident in his cell.', 'translation': "Bir hasta bakıcı öne atılarak Renfield'ın hücresinde korkunç ve esrarengiz bir kaza geçirdiğini bildirdi.", 'notes': 'mysterious accident: esrarengiz kaza.'}, {'id': 323, 'text': 'Dr. Seward and Van Helsing sprinted down the stone corridor to find the lunatic lying in a pool of blood.', 'translation': 'Doktor Seward ve Van Helsing taş koridordan aşağı koştular ve deliyi bir kan gölü içinde yatarken buldular.', 'notes': 'pool of blood: kan gölü.'}, {'id': 324, 'text': 'His skull was severely fractured, his back broken, and his chest crushed by superhuman physical pressure.', 'translation': 'Kafatası ağır şekilde çatlamıştı, beli kırılmıştı ve göğsü insanüstü bir fiziksel baskıyla ezilmişti.', 'notes': 'superhuman pressure: insanüstü baskı.'}, {'id': 325, 'text': 'Seward performed emergency surgery to relieve the pressure on his brain, restoring the dying man to temporary consciousness.', 'translation': 'Seward beynindeki baskıyı hafifletmek için acil ameliyat yaptı ve ölmekte olan adamın bilincini geçici olarak yerine getirdi.', 'notes': 'temporary consciousness: geçici bilinç.'}, {'id': 326, 'text': 'In his final, lucid moments, Renfield confessed the horrifying reality of what had transpired.', 'translation': 'Son ve aklı başında anlarında Renfield meydana gelen korkunç gerçeği itiraf etti.', 'notes': 'lucid moments: aklı başında/berrak anlar.'}, {'id': 327, 'text': '"The Count came to my barred window night after night in the form of a thick, whispering mist," Renfield murmured.', 'translation': '"Kont gece ardına gece kalın, fısıldayan bir sis kılığına bürünerek parmaklıklı pencereme geldi," diye mırıldandı Renfield.', 'notes': 'whispering mist: fısıldayan sis.'}, {'id': 328, 'text': '"He promised me countless lives, millions of moths and birds, if I would only invite him across the threshold."', 'translation': '"Eğer onu eşikten içeri davet edersem bana sayısız can, milyonlarca güve ve kuş vadetti."', 'notes': 'across the threshold: eşikten içeri.'}, {'id': 329, 'text': '"So I opened the window and welcomed him inside, believing his wicked and deceitful promises."', 'translation': '"Bu yüzden pencereyi açtım ve onun kötücül, aldatıcı vaatlerine kanarak onu içeri buyur ettim."', 'notes': 'deceitful promises: aldatıcı vaatler.'}, {'id': 330, 'text': '"Tonight, he slipped through the hallway toward Mrs. Harker\'s bedchamber to drain her gentle life away."', 'translation': '"Bu gece, Bayan Harker\'ın narin hayatını çekip almak için koridordan yatak odasına doğru süzüldü."', 'notes': 'drain life away: hayatını çekip almak/tüketmek.'}, {'id': 331, 'text': '"When I saw him going to harm that sweet lady who had shown me kindness, my heart revolted against the devil!"', 'translation': '"Bana şefkat göstermiş olan o tatlı hanımefendiye zarar vermeye gittiğini gördüğümde kalbim şeytana karşı isyan etti!"', 'notes': 'heart revolted: kalbi isyan etti.'}, {'id': 332, 'text': '"I leaped upon him, wrapping my arms around his body to hold him back from her door."', 'translation': '"Onu onun kapısından uzak tutmak için kollarımı bedenine dolayarak üzerine atıldım."', 'notes': 'hold him back: onu geride tutmak/alıkoymak.'}, {'id': 333, 'text': '"His red eyes burned like hellfire, and with one flick of his iron hands, he smashed me against the floor!"', 'translation': '"Kızıl gözleri cehennem ateşi gibi yandı ve demir ellerinin tek bir hareketiyle beni yere çarptı!"', 'notes': 'burned like hellfire: cehennem ateşi gibi yandı.'}, {'id': 334, 'text': 'With those final words, Renfield shuddered, breathed a ragged sigh, and expired upon the stone floor.', 'translation': 'Bu son sözlerle Renfield ürperdi, hırıltılı bir iç çekti ve taş zeminde can verdi.', 'notes': 'ragged sigh: hırıltılı iç çekiş.'}, {'id': 335, 'text': "Van Helsing's face turned white with absolute terror as the implication of Renfield's words struck him.", 'translation': "Renfield'ın sözlerinin anlamı zihnine çarparken Van Helsing'in yüzü mutlak bir dehşetle kireç gibi oldu.", 'notes': 'absolute terror: mutlak dehşet.'}, {'id': 336, 'text': '"My God! The monster is in the house this very moment, with Madam Mina!" the professor shouted.', 'translation': '"Aman Tanrım! Canavar tam şu anda evde, Madam Mina\'nın yanında!" diye haykırdı profesör.', 'notes': 'this very moment: tam şu anda.'}, {'id': 337, 'text': 'Jonathan Harker drew his sharp kukri knife, his eyes blazing with protective fury for his beloved wife.', 'translation': 'Jonathan Harker sevgili eşini koruma öfkesiyle gözleri alev alev yanarak keskin kavisli kamasını çekti.', 'notes': 'protective fury: korumacı öfke.'}, {'id': 338, 'text': 'The four men raced up the central staircase, taking three steps at a time in frantic desperation.', 'translation': 'Dört adam çılgın bir çaresizlikle basamakları üçer üçer atlayarak ana merdivenden yukarı koştular.', 'notes': 'frantic desperation: panik dolu çaresizlik.'}, {'id': 339, 'text': 'The bedroom door was locked securely from the inside, but Arthur and Quincey threw their heavy shoulders against it.', 'translation': 'Yatak odasının kapısı içeriden sıkıca kilitliydi fakat Arthur ve Quincey ağır omuzlarıyla kapıya yüklendiler.', 'notes': 'threw shoulders against: omuzlarıyla yüklendiler.'}, {'id': 340, 'text': 'With a thunderous splintering of oak, the lock tore loose, and the door burst open into the shadowy chamber.', 'translation': 'Meşenin gök gürültüsü gibi parçalanmasıyla kilit koptu ve kapı gölgeli odanın içine ardına kadar açıldı.', 'notes': 'thunderous splintering: gök gürültüsü gibi parçalanma.'}]}, {'page_no': 18, 'title': 'The Unholy Baptism of Blood', 'tr_title': 'Karanlığın Kan Vaftizi', 'vocab_focus': [('transfixed', 'donakalmış, dehşete düşmüş'), ('nightshirt', 'gecelik'), ('lacerate', 'yırtmak, parçalamak'), ('communion', 'ayin, birlik'), ('defiance', 'meydan okuma'), ('blasphemy', 'kutsala hakaret'), ('telepathy', 'zihinsel bağ, telepati'), ('retreat', 'geri çekilme')], 'sentences': [{'id': 341, 'text': 'The scene revealed by the silver moonlight froze the blood of every man standing in the doorway.', 'translation': 'Gümüş ay ışığının aydınlattığı manzara, kapı eşiğinde duran her adamın kanını dondurdu.', 'notes': 'froze the blood: kanını dondurdu.'}, {'id': 342, 'text': 'Jonathan Harker lay upon the mattress in a deep, supernatural trance, breathing heavily like a drugged man.', 'translation': 'Jonathan Harker şiltenin üzerinde derin, doğaüstü bir trans içinde uyuşturulmuş bir adam gibi ağır ağır nefes alıyordu.', 'notes': 'supernatural trance: doğaüstü trans.'}, {'id': 343, 'text': 'Beside him knelt Mina, her white nightdress stained with dark smears of fresh, glistening blood.', 'translation': 'Yanında Mina diz çökmüştü; beyaz geceliği taze, parıldayan kanın koyu lekeleriyle kirlenmişti.', 'notes': 'stained with smears: lekelerle kirlenmiş.'}, {'id': 344, 'text': 'Standing over her was Count Dracula, his tall form clad in his billowing black aristocratic cloak.', 'translation': "Üzerine dikilmiş olan kişi Kont Drakula'ydı; heybetli endamı dalgalanan siyah soylu pelerinine bürünmüştü.", 'notes': 'clad in cloak: pelerine bürünmüş.'}, {'id': 345, 'text': 'The vampire had torn open his own shirt with razor-sharp nails, opening a deep, bleeding wound in his chest.', 'translation': 'Vampir jilet gibi tırnaklarıyla kendi gömleğini yırtıp açmış ve göğsünde derin, kanayan bir yara açmıştı.', 'notes': 'torn open: yırtıp açmıştı.'}, {'id': 346, 'text': "With cruel, irresistible strength, his pale hand forced Mina's face against the bleeding laceration upon his breast.", 'translation': "Zalim ve karşı konulmaz bir güçle solgun eli, Mina'nın yüzünü göğsündeki kanayan yırtığa doğru bastırıyordu.", 'notes': 'bleeding laceration: kanayan yara/yırtık.'}, {'id': 347, 'text': "Mina was sobbing helplessly, compelled by dark hypnosis to drink the vampire's poisoned lifeblood.", 'translation': 'Mina çaresizce hıçkırıyordu; karanlık hipnozun zoruyla vampirin zehirli can kanını içmeye mecbur kalmıştı.', 'notes': 'poisoned lifeblood: zehirli can kanı.'}, {'id': 348, 'text': 'Hearing the door crash, Dracula raised his head, his face contorted into an expression of demonic fury and triumph.', 'translation': 'Kapının gürültüyle açıldığını duyan Drakula başını kaldırdı; yüzü şeytani bir öfke ve zafer ifadesiyle buruşmuştu.', 'notes': 'demonic fury: şeytani öfke.'}, {'id': 349, 'text': '"You think to baffle me with your petty human intellects?" the Count hissed with chilling contempt.', 'translation': '"Küçücük insan aklınızla beni alt edebileceğinizi mi sanıyorsunuz?" diye tısladı Kont kan donduran bir aşağılamayla.', 'notes': 'chilling contempt: kan donduran aşağılama.'}, {'id': 350, 'text': '"You have hunted my lairs, but now I have taken what you cherish most in this world!"', 'translation': '"İnlerimi avladınız fakat şimdi ben bu dünyada en çok değer verdiğiniz şeyi elinizden aldım!"', 'notes': 'cherish most: en çok değer vermek.'}, {'id': 351, 'text': '"She is now flesh of my flesh, blood of my blood, kin of my kin, and my obedient companion forever!"', 'translation': '"O artık etimden et, kanımdan kan, soyumdan soy ve sonsuza dek benim itaatkâr yoldaşımdır!"', 'notes': 'kin of my kin: soyumdan soy.'}, {'id': 352, 'text': '"When my call summons her across the night, she will come to me without resistance!"', 'translation': '"Benim çağrım onu gecenin içinden çağırdığında, bana direnç göstermeden tıpış tıpış gelecektir!"', 'notes': 'without resistance: direnç göstermeden.'}, {'id': 353, 'text': 'Van Helsing stepped forward fearlessly, raising a golden crucifix and a wafer of consecrated Host high in the air.', 'translation': 'Van Helsing korkusuzca öne çıktı; havaya altın bir haç ve kutsanmış ekmek parçasını kaldırdı.', 'notes': 'stepped forward fearlessly: korkusuzca öne çıktı.'}, {'id': 354, 'text': '"In the name of the Father, the Son, and the Holy Spirit, depart from this place, foul creature of darkness!"', 'translation': '"Baba, Oğul ve Kutsal Ruh adına bu mekândan defol git, karanlığın pis yaratığı!"', 'notes': 'foul creature: pis/iğrenç yaratık.'}, {'id': 355, 'text': 'The holy relics emitted a brilliant spiritual light that caused the vampire to shriek in searing agony.', 'translation': 'Kutsal emanetler, vampirin yakıcı bir acıyla çığlık atmasına yol açan parlak bir ruhani ışık yaydı.', 'notes': 'searing agony: yakıcı acı/ızdırap.'}, {'id': 356, 'text': 'Dracula released his grip upon Mina and swept backward, his cloak billowing like a vortex of black smoke.', 'translation': "Drakula Mina'nın üzerindeki tutuşunu bıraktı ve geriye savruldu; pelerini kara bir duman girdabı gibi dalgalanıyordu.", 'notes': 'vortex of black smoke: kara duman girdabı.'}, {'id': 357, 'text': 'Harker leaped forward with his knife, but the blade passed harmlessly through empty air as the monster dissolved into mist.', 'translation': 'Harker bıçağıyla öne atıldı fakat canavar sise dönüşürken namlu boş havayı zararsızca yardı geçti.', 'notes': 'passed through empty air: boş havayı yardı geçti.'}, {'id': 358, 'text': 'The dark vapor drifted out through the open window, vanishing into the nocturnal shadows of the garden.', 'translation': 'Koyu buhar açık pencereden dışarı süzüldü ve bahçenin gece gölgeleri arasında kaybolup gitti.', 'notes': 'nocturnal shadows: gece gölgeleri.'}, {'id': 359, 'text': 'Left alone upon the bed, Mina collapsed into hysterical weeping, frantically wiping her blood-smeared mouth on the sheets.', 'translation': 'Yatakta yapayalnız kalan Mina sinir krizleri içinde ağlayarak yere yığıldı; kan sıvanmış ağzını çarşaflara telaşla sildi.', 'notes': 'hysterical weeping: histerik ağlama.'}, {'id': 360, 'text': '"Unclean! Unclean!" she shrieked in horror; "I am tainted by the touch of the fiend!"', 'translation': '"Murdar! Murdar!" diye dehşetle haykırdı; "O iblisin dokunuşuyla lekelendim ben!"', 'notes': 'tainted by the touch: dokunuşla lekelenmiş.'}]}, {'page_no': 19, 'title': 'The Scorching Sacred Host', 'tr_title': 'Dağlayan Kutsal Ekmek ve Lekelenen Alın', 'vocab_focus': [('tainted', 'lekelenmiş, kirlenmiş'), ('scorch', 'yakmak, dağlamak'), ('scar', 'yara izi'), ('damned', 'lanetlenmiş'), ('purity', 'saflık, masumiyet'), ('consolation', 'teselli, avuntu'), ('brotherhood', 'kardeşlik'), ('determination', 'azim, kararlılık')], 'sentences': [{'id': 361, 'text': 'Jonathan awoke from his heavy stupor and looked around the room in bewildered disorientation.', 'translation': 'Jonathan o ağır uyuşukluğundan uyandı ve şaşkın bir sersemlikle odanın etrafına bakındı.', 'notes': 'bewildered disorientation: şaşkın sersemlik.'}, {'id': 362, 'text': 'Seeing his wife sobbing and covered in blood, he gathered her into his arms, kissing her tear-streaked face passionately.', 'translation': 'Karısını hıçkırıklar içinde ve kana bulanmış görünce onu kollarının arasına aldı; gözyaşıyla ıslanmış yüzünü tutkuyla öptü.', 'notes': 'tear-streaked face: gözyaşlarıyla ıslanmış yüz.'}, {'id': 363, 'text': '"Do not touch me, Jonathan!" Mina cried out in despair; "I am polluted and unworthy to be your wife!"', 'translation': '"Bana dokunma Jonathan!" diye çaresizce feryat etti Mina; "Ben kirlendim ve senin karın olmaya layık değilim!"', 'notes': 'polluted and unworthy: kirlenmiş ve layık olmayan.'}, {'id': 364, 'text': '"You are the purest, noblest soul upon this earth," Jonathan vowed, holding her even closer to his chest.', 'translation': '"Sen bu yeryüzündeki en saf, en asil ruhsun," diye ant içti Jonathan; onu göğsüne daha da sıkı bastırarak.', 'notes': 'noblest soul: en asil ruh.'}, {'id': 365, 'text': 'Van Helsing stepped forward with tears in his eyes, wishing to impart divine comfort and blessing to the suffering woman.', 'translation': 'Van Helsing acı çeken kadına ilahi bir teselli ve bereket bahşetmek isteyerek gözlerinde yaşlarla öne çıktı.', 'notes': 'impart divine comfort: ilahi teselli bahşetmek.'}, {'id': 366, 'text': "He took a small wafer of the consecrated Host from his golden pyx and placed it gently upon Mina's forehead.", 'translation': "Altın kutusundan kutsanmış ekmekten küçük bir parça çıkardı ve onu nazikçe Mina'nın alnına koydu.", 'notes': 'golden pyx: kutsal ekmek kutusu.'}, {'id': 367, 'text': 'The moment the sacred bread touched her skin, an appalling hiss sounded like cold water dropped upon red-hot iron!', 'translation': 'Kutsal ekmek tenine değer değmez, kızgın demire damlayan soğuk su gibi korkunç bir cızırtı duyuldu!', 'notes': 'appalling hiss: korkunç cızırtı/tıslama.'}, {'id': 368, 'text': 'Mina shrieked in piercing agony as the consecrated wafer burned through her flesh like a glowing ember.', 'translation': 'Kutsanmış ekmek yanan bir kor gibi etini dağlarken Mina kulakları tırmalayan bir acıyla çığlık attı.', 'notes': 'glowing ember: yanan kor/köz.'}, {'id': 369, 'text': 'When Van Helsing pulled the wafer away in horror, a permanent, red circular scar was branded into her forehead.', 'translation': 'Van Helsing dehşet içinde ekmeği geri çektiğinde, alnına kalıcı, kırmızı yuvarlak bir yara izi dağlanmıştı.', 'notes': 'branded into forehead: alnına dağlanmış.'}, {'id': 370, 'text': 'Mina covered her face with her hands, trembling uncontrollably beneath the terrible sign of spiritual damnation.', 'translation': 'Mina elleriyle yüzünü kapattı; ruhani lanetin o korkunç işareti altında kontrolsüzce titredi.', 'notes': 'spiritual damnation: ruhani lanet.'}, {'id': 371, 'text': '"Even God has rejected me!" she wept bitterly; "I must wear this brand of shame until I am dead!"', 'translation': '"Tanrı bile beni reddetti!" diye acı acı ağladı; "Ölene kadar bu utanç damgasını taşımak zorundayım!"', 'notes': 'brand of shame: utanç damgası.'}, {'id': 372, 'text': '"No, dear lady," Van Helsing said with resolute gentleness, kneeling beside the weeping couple.', 'translation': '"Hayır sevgili hanımefendi," dedi Van Helsing ağlayan çiftin yanında diz çökerek kararlı bir nezaketle.', 'notes': 'resolute gentleness: kararlı nezaket.'}, {'id': 373, 'text': '"That scar is not a sign of God\'s rejection, but a physical proof of the poison Dracula forced upon you."', 'translation': '"O yara izi Tanrı\'nın reddinin işareti değil, Drakula\'nın seni zorladığı zehrin fiziksel bir kanıtıdır."', 'notes': 'physical proof: fiziksel kanıt.'}, {'id': 374, 'text': '"When that monster is slain, the poison will vanish, and that forehead shall be smooth and pure once more!"', 'translation': '"O canavar katledildiğinde zehir yok olacak ve o alın bir kez daha pürüzsüz ve tertemiz parlayacaktır!"', 'notes': 'smooth and pure: pürüzsüz ve saf.'}, {'id': 375, 'text': "Arthur Holmwood, Quincey Morris, and Dr. Seward stepped forward, each placing a hand upon Harker's shoulder.", 'translation': "Arthur Holmwood, Quincey Morris ve Doktor Seward öne çıktılar; her biri bir elini Harker'ın omzuna koydu.", 'notes': 'placing a hand: elini koyarak.'}, {'id': 376, 'text': '"We swear to you, Mina, by everything we hold sacred, that we will not rest until Dracula is destroyed," Arthur proclaimed.', 'translation': '"Sana kutsal bildiğimiz her şey üzerine yemin ederiz Mina; Drakula yok edilene kadar bize rahat huzur yok," dedi Arthur.', 'notes': 'not rest until destroyed: yok edilene kadar rahat yok.'}, {'id': 377, 'text': 'Quincey Morris drew his large bowie knife, kissing the steel blade as a pledge of unwavering loyalty.', 'translation': 'Quincey Morris sarsılmaz bir sadakat yemini olarak çelik namluyu öperek büyük avcı bıçağını çekti.', 'notes': 'pledge of loyalty: sadakat yemini.'}, {'id': 378, 'text': 'The hunters understood that their mission was now an urgent race against the ticking clock of eternity.', 'translation': 'Avcılar artık görevlerinin ebediyetin işleyen saatine karşı acil bir yarış olduğunu anladılar.', 'notes': 'ticking clock of eternity: ebediyetin işleyen saati.'}, {'id': 379, 'text': 'If Dracula was not eliminated swiftly, Mina would die and awaken as an immortal vampire like Lucy Westenra.', 'translation': 'Eğer Drakula hızla ortadan kaldırılmazsa Mina ölecek ve Lucy Westenra gibi ölümsüz bir vampir olarak uyanacaktı.', 'notes': 'immortal vampire: ölümsüz vampir.'}, {'id': 380, 'text': 'With grim determination, the company prepared to hunt down the remaining twenty-one boxes hidden across London.', 'translation': 'Büyük bir azim ve kararlılıkla ekip, Londra geneline gizlenmiş kalan yirmi bir sandığı avlamaya hazırlandı.', 'notes': 'grim determination: çetin bir kararlılık.'}]}, {'page_no': 20, 'title': 'Destroying the London Lairs', 'tr_title': 'Londra İnlerinin Yok Edilmesi', 'vocab_focus': [('carter', 'arabacı, nakliyeci'), ('hire', 'kiralamak'), ('lair', 'in, sığınak'), ('warehouse', 'depo'), ('sterilization', 'arındırma, etkisiz kılma'), ('ambush', 'pusu'), ('confrontation', 'yüzleşme'), ('pursuit', 'kovalama, takip')], 'sentences': [{'id': 381, 'text': "Using shipping records that Mina had organized, the hunters interviewed carters who had moved the Count's cargo.", 'translation': "Mina'nın düzenlediği nakliye kayıtlarını kullanan avcılar, Kont'un yükünü taşıyan arabacılarla görüştüler.", 'notes': 'shipping records: nakliye kayıtları.'}, {'id': 382, 'text': 'They discovered that six boxes had been delivered to an old Georgian townhouse in Bermondsey, south of the Thames.', 'translation': "Altı sandığın Thames'in güneyinde, Bermondsey'deki eski bir Georgian konağına teslim edildiğini keşfettiler.", 'notes': 'townhouse: şehir konağı.'}, {'id': 383, 'text': 'Another six boxes were hidden in a damp, abandoned warehouse located near the docks of Mile End.', 'translation': 'Diğer altı sandık ise Mile End rıhtımlarının yakınında bulunan nemli, terk edilmiş bir depoya gizlenmişti.', 'notes': 'abandoned warehouse: terk edilmiş depo.'}, {'id': 384, 'text': 'The final nine boxes had been transported to a fashionable mansion on Piccadilly in the heart of London.', 'translation': "Son dokuz sandık ise Londra'nın kalbinde, Piccadilly'deki lüks bir malikaneye nakledilmişti.", 'notes': 'fashionable mansion: lüks/gözde malikane.'}, {'id': 385, 'text': 'Armed with skeleton keys and sacred supplies, the men raided the Bermondsey house during the daylight hours.', 'translation': "Maymuncuklar ve kutsal mühimmatla donanan adamlar gündüz saatlerinde Bermondsey'deki eve baskın düzenlediler.", 'notes': 'skeleton keys: maymuncuk anahtarlar.'}, {'id': 386, 'text': 'They found the six boxes in the dark cellar, placed consecrated wafers in each, and rendered them spiritually inert.', 'translation': 'Karanlık mahzende altı sandığı buldular, her birine kutsanmış ekmek koydular ve onları ruhani olarak etkisiz hale getirdiler.', 'notes': 'spiritually inert: ruhani olarak etkisiz/hareketsiz.'}, {'id': 387, 'text': 'Next, they traveled swiftly across London to the Mile End warehouse, discovering another six earth-filled containers.', 'translation': "Ardından hızla Londra'yı boydan boya geçerek Mile End deposuna ulaştılar ve toprak dolu diğer altı sandığı buldular.", 'notes': 'earth-filled containers: toprak dolu sandıklar.'}, {'id': 388, 'text': 'Van Helsing sanctified all six, leaving only the nine boxes at the Piccadilly residence to be destroyed.', 'translation': "Van Helsing altısını da kutsadı; geriye yok edilmek üzere yalnızca Piccadilly'deki konuttaki dokuz sandık kaldı.", 'notes': 'sanctified: kutsadı, arındırdı.'}, {'id': 389, 'text': 'The hunters forced their way into the Piccadilly mansion through a rear service entrance.', 'translation': 'Avcılar arka servis girişinden zorla Piccadilly malikanesine girdiler.', 'notes': 'forced their way into: zorla içeri girdiler.'}, {'id': 390, 'text': 'Searching the spacious dining room, they discovered eight massive wooden boxes stacked neatly against the wall.', 'translation': 'Geniş yemek odasını ararken duvara düzgünce istiflenmiş sekiz devasa tahta sandık keşfettiler.', 'notes': 'stacked neatly: düzgünce istiflenmiş.'}, {'id': 391, 'text': '"One box is missing!" Jonathan warned anxiously; "there should be nine containers in this house!"', 'translation': '"Bir sandık eksik!" diye uyardı Jonathan endişeyle; "Bu evde dokuz sandık olması gerekirdi!"', 'notes': 'one box is missing: bir sandık eksik.'}, {'id': 392, 'text': 'Before they could search further, the front door rattled and a key turned smoothly in the heavy brass lock.', 'translation': 'Daha fazla arayamadan ön kapı sarsıldı ve anahtar ağır pirinç kilidin içinde pürüzsüzce döndü.', 'notes': 'rattled: sarsıldı, takırdadı.'}, {'id': 393, 'text': "Count Dracula entered the hallway, dressed impeccably in fashionable gentleman's attire, carrying an umbrella.", 'translation': 'Kont Drakula şık bir beyefendi kıyafeti içinde kusursuzca giyinmiş ve elinde bir şemsiyeyle koridora girdi.', 'notes': "gentleman's attire: beyefendi kıyafeti."}, {'id': 394, 'text': "Seeing the desecrated boxes and his enemies standing armed before him, Dracula's face twisted into demonic rage.", 'translation': "Arındırılmış sandıkları ve silahlı düşmanlarını karşısında gören Drakula'nın yüzü şeytani bir öfkeyle çarpıldı.", 'notes': 'twisted into rage: öfkeyle çarpıldı.'}, {'id': 395, 'text': 'He lunged at the group with blinding speed, his eyes blazing like twin furnaces of hell.', 'translation': 'Gözleri cehennemin ikiz fırınları gibi alev alev yanarak göz kamaştırıcı bir hızla gruba saldırdı.', 'notes': 'twin furnaces of hell: cehennemin ikiz ocakları.'}, {'id': 396, 'text': "Jonathan Harker swung his heavy kukri blade in a vicious arc, slashing Dracula's coat across the chest.", 'translation': "Jonathan Harker ağır kavisli kamasını sert bir kavisle savurarak Drakula'nın göğsündeki paltoyu yardı.", 'notes': 'vicious arc: sert/yırtıcı bir kavis.'}, {'id': 397, 'text': 'A cascade of gold sovereigns and ancient coins poured from the sliced pockets onto the parquet floor.', 'translation': 'Yarılan ceplerden parke zemine altın sikkeler ve kadim paralardan oluşan bir şelale döküldü.', 'notes': 'gold sovereigns: altın sikkeler/liralalar.'}, {'id': 398, 'text': 'Dracula scrambled backward, hissed like a giant serpent, and vaulted through a high stained-glass window into the courtyard.', 'translation': 'Drakula geriye sıçradı, dev bir yılan gibi tısladı ve yüksek bir vitray pencereden atlayarak avluya indi.', 'notes': 'vaulted through window: pencereden atladı.'}, {'id': 399, 'text': '"You shall pay dearly for this!" Dracula\'s voice echoed menacingly from the foggy street outside.', 'translation': '"Bunun bedelini çok ağır ödeyeceksiniz!" diye yankılandı Drakula\'nın sesi dışarıdaki sisli caddeden tehditkâr bir şekilde.', 'notes': 'pay dearly: bedelini ağır ödemek.'}, {'id': 400, 'text': 'Van Helsing sanctified the eight remaining boxes; of the fifty containers brought to England, only one single box remained!', 'translation': "Van Helsing kalan sekiz sandığı da kutsadı; İngiltere'ye getirilen elli sandıktan geriye sadece tek bir sandık kalmıştı!", 'notes': 'only one box remained: yalnızca bir sandık kaldı.'}]}, {'page_no': 21, 'title': 'The Dawn Hypnosis and the Black Sea', 'tr_title': 'Şafak Hipnozu ve Karadeniz Yolculuğu', 'vocab_focus': [('hypnotism', 'hipnoz'), ('telepathic', 'telepatik'), ('creaking', 'gıcırdama'), ('tide', 'gelgit, deniz akıntısı'), ('schooner', 'uskuna, yelkenli'), ('harbor', 'liman'), ('voyage', 'deniz yolculuğu'), ('destination', 'varış yeri, hedef')], 'sentences': [{'id': 401, 'text': "Back at the asylum, Van Helsing realized that Dracula's blood bond with Mina could be turned against the monster.", 'translation': "Akıl hastanesine döndüklerinde Van Helsing, Drakula'nın Mina ile kurduğu kan bağının canavara karşı kullanılabileceğini fark etti.", 'notes': 'blood bond: kan bağı.'}, {'id': 402, 'text': 'Because Dracula had forced her to drink his blood, a subconscious telepathic link existed between them.', 'translation': 'Drakula onu kendi kanını içmeye zorladığı için, aralarında bilinçaltı telepatik bir bağ oluşmuştu.', 'notes': 'subconscious telepathic link: bilinçaltı telepatik bağ.'}, {'id': 403, 'text': 'This spiritual connection was strongest at the mystical twilight moments of dawn and dusk.', 'translation': 'Bu ruhani bağlantı şafak ve alacakaranlığın o mistik yarı aydınlık anlarında en güçlü seviyesine ulaşıyordu.', 'notes': 'twilight moments: alacakaranlık anları.'}, {'id': 404, 'text': "Just before sunrise the following morning, Van Helsing placed his hands on Mina's temples and gently hypnotized her.", 'translation': "Ertesi sabah gün doğumundan hemen önce Van Helsing ellerini Mina'nın şakaklarına koydu ve onu usulca hipnotize etti.", 'notes': 'gently hypnotized: usulca hipnotize etti.'}, {'id': 405, 'text': '"Where are you, Madam Mina? What do you see and hear?" the Dutch professor asked in a soothing, hypnotic whisper.', 'translation': '"Neredesiniz Madam Mina? Neler görüp neler işitiyorsunuz?" diye sordu Hollandalı profesör yatıştırıcı, hipnotik bir fısıltıyla.', 'notes': 'soothing whisper: teskin edici fısıltı.'}, {'id': 406, 'text': 'In a distant, trance-like monotone, Mina answered: "I hear the sound of lapping water against wooden timbers."', 'translation': 'Uzak, trans benzeri tekdüze bir sesle Mina yanıt verdi: "Ahşap kalaslara çarpan suyun sesini duyuyorum."', 'notes': 'lapping water: şıpırdayan su.'}, {'id': 407, 'text': '"There is the creaking of tall masts, the rattle of anchor chains, and sailors shouting in a foreign tongue."', 'translation': '"Yüksek direklerin gıcırtısı, çapa zincirlerinin şakırtısı ve yabancı bir dilde bağıran denizciler var."', 'notes': 'rattle of anchor chains: çapa zincirlerinin şakırtısı.'}, {'id': 408, 'text': '"I feel the rolling motion of ocean waves beneath me; darkness surrounds me in a narrow wooden enclosure."', 'translation': '"Altımda okyanus dalgalarının sallantısını hissediyorum; dar ahşap bir bölmenin içinde beni karanlık kuşatıyor."', 'notes': 'rolling motion: sallantı, çalkantı.'}, {'id': 409, 'text': 'Van Helsing opened his eyes wide with triumphant realization: "Dracula is at sea aboard a ship!"', 'translation': 'Van Helsing muzaffer bir kavrayışla gözlerini faltaşı gibi açtı: "Drakula bir gemide, denizde!"', 'notes': 'triumphant realization: muzaffer kavrayış.'}, {'id': 410, 'text': 'The Count had taken his single remaining earth box and fled from England before the hunters could destroy him.', 'translation': "Kont elinde kalan o tek toprak sandığını almış ve avcılar kendisini yok edemeden İngiltere'den kaçmıştı.", 'notes': "fled from England: İngiltere'den kaçtı."}, {'id': 411, 'text': "Jonathan rushed immediately to the maritime shipping offices at Lloyd's of London to inspect vessel departures.", 'translation': "Jonathan gemi hareketlerini incelemek için derhal Londra Lloyd's denizcilik nakliyat ofislerine koştu.", 'notes': 'maritime shipping offices: deniz nakliyat büroları.'}, {'id': 412, 'text': 'He discovered that a sailing schooner named the Czarina Catherine had cleared the Thames estuary on the morning tide.', 'translation': 'Czarina Catherine adında bir yelkenli uskunun sabah cezir akıntısıyla Thames halicinden denize açıldığını keşfetti.', 'notes': 'cleared the estuary: haliçten denize açıldı.'}, {'id': 413, 'text': 'The ship was bound on a four-week voyage across the Mediterranean to the Black Sea port of Varna.', 'translation': "Gemi Akdeniz üzerinden Karadeniz limanı Varna'ya doğru dört haftalık bir sefere çıkmıştı.", 'notes': 'bound on a voyage: sefere çıkmış.'}, {'id': 414, 'text': 'A tall, foreign nobleman dressed in black had purchased passage at the final moment, boarding with a large wooden crate.', 'translation': 'Siyahlara bürünmüş uzun boylu yabancı bir soylu son anda bilet almış ve büyük bir tahta sandıkla gemiye binmişti.', 'notes': 'purchased passage: bilet satın aldı/yolculuk hakkı aldı.'}, {'id': 415, 'text': '"He is returning to his castle in Transylvania to recover his strength," Van Helsing declared to the assembled company.', 'translation': '"Gücünü yeniden toplamak için Transilvanya\'daki şatosuna geri dönüyor," diye ilan etti Van Helsing toplanan ekibe.', 'notes': 'recover strength: gücünü toplamak.'}, {'id': 416, 'text': '"He believes he has escaped our reach, but we possess an advantage he does not anticipate."', 'translation': '"Bizim erişimimizden kaçtığını sanıyor fakat onun hesaba katmadığı bir üstünlüğe sahibiz."', 'notes': 'advantage he does not anticipate: tahmin etmediği bir avantaj.'}, {'id': 417, 'text': '"A sailing ship requires weeks to navigate through the Straits of Gibraltar and across the Mediterranean."', 'translation': '"Bir yelkenli geminin Cebelitarık Boğazı\'ndan geçip Akdeniz\'i aşması haftalar sürer."', 'notes': 'Straits of Gibraltar: Cebelitarık Boğazı.'}, {'id': 418, 'text': '"We can board the high-speed Orient Express train and reach the Black Sea port of Varna in less than three days!"', 'translation': '"Biz yüksek hızlı Şark Ekspresi trenine binip Karadeniz limanı Varna\'ya üç günden kısa sürede ulaşabiliriz!"', 'notes': 'high-speed train: yüksek hızlı tren.'}, {'id': 419, 'text': '"We shall wait upon the harbor pier in Varna and destroy him the very instant his ship drops anchor!"', 'translation': '"Varna\'daki liman iskelesinde bekleyecek ve gemisi demir attığı an onu yok edeceğiz!"', 'notes': 'drops anchor: demir atar.'}, {'id': 420, 'text': 'Mina insisted on accompanying them, knowing her telepathic connection was the only compass that could track their quarry.', 'translation': 'Telepatik bağının avlarını takip edebilecek yegane pusula olduğunu bilen Mina onlara eşlik etmekte ısrar etti.', 'notes': 'track quarry: avı takip etmek.'}]}, {'page_no': 22, 'title': 'The Orient Express and the Deceptive Fog', 'tr_title': 'Şark Ekspresi ve Aldatıcı Sis', 'vocab_focus': [('express', 'hızlı tren'), ('consulate', 'konsolosluk'), ('telegram', 'telgraf'), ('deflection', 'yön değiştirme'), ('diverted', 'yönlendirilmiş'), ('tributary', 'ırmak kolu'), ('interception', 'yolunu kesme'), ('strategy', 'strateji')], 'sentences': [{'id': 421, 'text': 'Armed with Winchester rifles, silver knives, and sacred supplies, the five hunters and Mina boarded the Orient Express.', 'translation': "Winchester tüfekleri, gümüş bıçaklar ve kutsal malzemelerle donanan beş avcı ve Mina Şark Ekspresi'ne bindiler.", 'notes': 'sacred supplies: kutsal mühimmat/malzemeler.'}, {'id': 422, 'text': 'The steam locomotive thundered across France, Germany, Austria, and Romania, racing against the sailing ship.', 'translation': 'Buharlı lokomotif yelkenli gemiyle yarışarak Fransa, Almanya, Avusturya ve Romanya boyunca kükredi.', 'notes': 'thundered across: gürleyerek aştı.'}, {'id': 423, 'text': 'They arrived at the Bulgarian port of Varna in mid-October, establishing a permanent watch along the harbor docks.', 'translation': "Ekim ortasında Bulgar limanı Varna'ya vardılar ve liman rıhtımları boyunca sürekli bir nöbet kurdular.", 'notes': 'permanent watch: daimi nöbet.'}, {'id': 424, 'text': 'Arthur secured diplomatic assistance from the British Consul, arranging for immediate legal authority to board the ship.', 'translation': "Arthur İngiliz Konsolosu'ndan diplomatik destek sağladı; gemiye çıkmak için derhal geçerli yasal yetki temin etti.", 'notes': 'legal authority: yasal yetki.'}, {'id': 425, 'text': "Every morning at dawn and every evening at sunset, Van Helsing hypnotized Mina to track Dracula's progress.", 'translation': "Her sabah şafakta ve her akşam günbatımında Van Helsing Drakula'nın ilerleyişini takip etmek için Mina'yı hipnotize etti.", 'notes': 'track progress: ilerlemeyi takip etmek.'}, {'id': 426, 'text': 'Each time, Mina reported the same sensory impressions: "Still water rushing past, sails snapping, and utter darkness."', 'translation': 'Her seferinde Mina aynı duyusal izlenimleri aktardı: "Hâlâ yanından sular akıyor, yelkenler çarpıyor ve zifiri karanlık var."', 'notes': 'sensory impressions: duyusal izlenimler.'}, {'id': 427, 'text': 'Days lengthened into weeks, but the Czarina Catherine failed to appear on the horizon of the Black Sea.', 'translation': 'Günler haftalara uzadı fakat Czarina Catherine bir türlü Karadeniz ufkunda görünmedi.', 'notes': 'lengthened into weeks: haftalara uzadı.'}, {'id': 428, 'text': 'On the twenty-fourth of October, Mina awoke from her dawn trance with an expression of acute agitation.', 'translation': "Yirmi dört Ekim'de Mina şiddetli bir telaş ifadesiyle şafak transından uyandı.", 'notes': 'acute agitation: şiddetli telaş/huzursuzluk.'}, {'id': 429, 'text': '"The water sounds different today; it is flowing smoothly, not surging with ocean waves," she murmured.', 'translation': '"Su sesi bugün farklı geliyor; okyanus dalgalarıyla kabarmıyor, düzgünce akıyor," diye mırıldandı.', 'notes': 'flowing smoothly: düzgünce akarak.'}, {'id': 430, 'text': '"I hear river birds, church bells in the distance, and men speaking Romanian on nearby barges."', 'translation': '"Nehir kuşlarını, uzaktaki kilise çanlarını ve yakındaki mavnalarda Romence konuşan adamları duyuyorum."', 'notes': 'nearby barges: yakındaki mavnalar.'}, {'id': 431, 'text': 'A few hours later, an urgent telegram arrived from the British Vice-Consul in the Romanian port of Galatz.', 'translation': "Birkaç saat sonra Romanya'nın Galatz limanındaki İngiliz Muavin Konsolosu'ndan acil bir telgraf geldi.", 'notes': 'urgent telegram: acil telgraf.'}, {'id': 432, 'text': 'The Czarina Catherine had bypassed Varna entirely under cover of a dense, unnatural fog and docked at Galatz!', 'translation': "Czarina Catherine yoğun, tekinsiz bir sisin örtüsü altında Varna'yı tamamen pas geçmiş ve Galatz'a demirlemişti!", 'notes': 'under cover of fog: sis örtüsü altında.'}, {'id': 433, 'text': 'Dracula had used his weather magic to divert the vessel sixty miles up the Danube River without stopping at Varna.', 'translation': "Drakula hava büyüsünü kullanarak gemiyi Varna'da durmaksızın Tuna Nehri boyunca altmış mil içeri yönlendirmişti.", 'notes': 'weather magic: hava büyüsü.'}, {'id': 434, 'text': '"He knew we were waiting for him!" Quincey Morris exclaimed, striking his fist against the table in frustration.', 'translation': '"Onu beklediğimizi biliyordu!" diye haykırdı Quincey Morris hayal kırıklığıyla yumruğunu masaya vurarak.', 'notes': 'striking fist: yumruk vurarak.'}, {'id': 435, 'text': "Van Helsing realized that the telepathic link worked both ways: Dracula had sensed their presence through Mina's mind!", 'translation': "Van Helsing telepatik bağın çift taraflı çalıştığını anladı: Drakula onların varlığını Mina'nın zihninden hissetmişti!", 'notes': 'worked both ways: çift taraflı çalıştı.'}, {'id': 436, 'text': '"We must not despair," Van Helsing urged calmly; "he is still trapped in his wooden box until sunset."', 'translation': '"Umutsuzluğa kapılmamalıyız," dedi Van Helsing sakince; "o günbatımına kadar hâlâ tahta sandığının içinde kapana kısılmış durumda."', 'notes': 'must not despair: umutsuzluğa kapılmamalıyız.'}, {'id': 437, 'text': 'The company caught an express train northward to Galatz, arriving late that same evening at the Danube docks.', 'translation': "Ekip Galatz'a doğru kuzeye giden bir ekspres trene bindi ve aynı akşam geç saatlerde Tuna rıhtımlarına vardı.", 'notes': 'Danube docks: Tuna rıhtımları.'}, {'id': 438, 'text': 'They discovered that the wooden box had already been unloaded that afternoon by a local merchant named Hildesheim.', 'translation': 'Ahşap sandığın o öğleden sonra Hildesheim adında yerel bir tüccar tarafından çoktan boşaltıldığını keşfettiler.', 'notes': 'local merchant: yerel tüccar.'}, {'id': 439, 'text': 'Hildesheim had delivered the crate to a band of armed Slovak gypsies who were transporting it inland by river wagon.', 'translation': 'Hildesheim sandığı, onu nehir boyu giden bir vagonla iç kısımlara taşıyan silahlı bir grup Slovak çingene teslim etmişti.', 'notes': 'armed Slovak gypsies: silahlı Slovak çingeneler.'}, {'id': 440, 'text': 'Dracula was heading straight for Castle Dracula, racing against time to reach his unholy sanctuary.', 'translation': "Drakula o lanetli sığınağına ulaşmak için zamana karşı yarışarak doğruca Drakula Şatosu'na yönelmişti.", 'notes': 'unholy sanctuary: kutsal olmayan/lanetli sığınak.'}]}, {'page_no': 23, 'title': 'The Triple Pursuit into the Wild Mountains', 'tr_title': 'Vahşi Dağlara Doğru Üçlü Takip', 'vocab_focus': [('steam launch', 'buharlı istimbot'), ('cavalry', 'süvari, atlılar'), ('bivouac', 'açık ordugah, mola yeri'), ('defile', 'dar geçit'), ('tributary', 'yan dere, çay'), ('perilous', 'tehlikeli, çetin'), ('rendezvous', 'buluşma yeri'), ('reinforcement', 'takviye, destek')], 'sentences': [{'id': 441, 'text': 'At Galatz, the hunters studied detailed maps of the Carpathian river systems and mountain passes.', 'translation': "Galatz'da avcılar Karpat nehir sistemlerinin ve dağ geçitlerinin ayrıntılı haritalarını incelediler.", 'notes': 'mountain passes: dağ geçitleri.'}, {'id': 442, 'text': "The gypsies were transporting Dracula's box on a heavy wagon following the Sereth River toward the Borgo Pass.", 'translation': "Çingeneler Drakula'nın sandığını Siret Nehri'ni takip ederek Borgo Geçidi'ne doğru ağır bir vagonla taşıyorlardı.", 'notes': 'heavy wagon: ağır vagon/araba.'}, {'id': 443, 'text': 'Van Helsing devised a brilliant three-pronged pursuit strategy to trap the fleeing vampire from all directions.', 'translation': 'Van Helsing kaçan vampiri her yönden kıstırmak için zekice üç kollu bir takip stratejisi tasarladı.', 'notes': 'three-pronged strategy: üç kollu strateji.'}, {'id': 444, 'text': 'Jonathan Harker and Arthur Holmwood hired a high-speed steam launch to pursue the gypsies directly up the river.', 'translation': 'Jonathan Harker ve Arthur Holmwood çingeneleri doğrudan nehir boyunca kovalamak için yüksek hızlı bir buharlı istimbot kiraladılar.', 'notes': 'high-speed steam launch: hızlı buharlı istimbot.'}, {'id': 445, 'text': 'Dr. John Seward and Quincey Morris purchased swift, sturdy horses to ride along the riverbank trails.', 'translation': 'Doktor John Seward ve Quincey Morris nehir kıyısı patikalarında sürmek üzere hızlı ve sağlam atlar satın aldılar.', 'notes': 'riverbank trails: nehir kıyısı patikaları.'}, {'id': 446, 'text': 'Van Helsing and Mina would travel by horse carriage through the mountains straight to Castle Dracula itself.', 'translation': "Van Helsing ve Mina ise at arabasıyla dağların arasından doğruca bizzat Drakula Şatosu'na gideceklerdi.", 'notes': 'horse carriage: at arabası.'}, {'id': 447, 'text': '"Our duty is to purify the castle and destroy his lair before he can ever enter its gates," Van Helsing explained.', 'translation': '"Bizim görevimiz o kapılarından içeri adım atamadan şatoyu arındırmak ve inini yok etmektir," diye açıkladı Van Helsing.', 'notes': 'purify the castle: şatoyu arındırmak.'}, {'id': 448, 'text': 'They embraced warmly, knowing some among them might never return alive from the freezing wilderness.', 'translation': 'Aralarından bazılarının o dondurucu yaban hayatından asla sağ dönemeyebileceğini bilerek birbirlerine sıcakça sarıldılar.', 'notes': 'freezing wilderness: dondurucu yaban.'}, {'id': 449, 'text': 'Jonathan and Arthur steamed relentlessly up the winding river, their boat cutting through the icy mountain current.', 'translation': 'Jonathan ve Arthur tekneleri buzlu dağ akıntısını yararak kıvrımlı nehirde durmaksızın ilerlediler.', 'notes': 'cutting through current: akıntıyı yararak.'}, {'id': 450, 'text': 'Along the forested banks, Seward and Quincey rode through day and night, their rifles ready in their saddle holsters.', 'translation': 'Ormanlık kıyılar boyunca Seward ve Quincey tüfekleri eyer kılıflarında hazır halde gece gündüz at sürdüler.', 'notes': 'saddle holsters: eyer kılıfları.'}, {'id': 451, 'text': 'Meanwhile, Van Helsing and Mina traveled in a sturdy carriage through the increasingly wild and snowy landscape.', 'translation': 'Bu sırada Van Helsing ve Mina giderek vahşileşen ve karlılaşan coğrafyada sağlam bir faytonla yol alıyorlardı.', 'notes': 'sturdy carriage: sağlam fayton.'}, {'id': 452, 'text': 'As they climbed higher into the Carpathians, winter descended with fierce blizzards and howling gales.', 'translation': 'Karpatların daha yükseklerine tırmandıkça, şiddetli tipiler ve uğuldayan fırtınalarla birlikte kış bastırdı.', 'notes': 'fierce blizzards: şiddetli tipiler.'}, {'id': 453, 'text': 'The cold grew bitter, freezing the mountain streams and dusting the tall pine forests in heavy white snow.', 'translation': 'Soğuk dondurucu hale geldi; dağ derelerini dondurdu ve heybetli çam ormanlarını kalın beyaz bir karla kapladı.', 'notes': 'grew bitter: amansız/şiddetli hale geldi.'}, {'id': 454, 'text': 'Mina noticed with quiet terror that she was growing more lethargic during the day and more alert after dusk.', 'translation': 'Mina gündüzleri daha uyuşuk, alacakaranlıktan sonra ise daha tetikte olduğunu sessiz bir dehşetle fark etti.', 'notes': 'more lethargic: daha uyuşuk/halsiz.'}, {'id': 455, 'text': 'Her eyes occasionally flashed with strange red glints, and she found it increasingly difficult to pray.', 'translation': 'Gözleri zaman zaman garip kırmızı parıltılarla çakıyordu ve dua etmeyi giderek daha zor buluyordu.', 'notes': 'red glints: kızıl pırıltılar.'}, {'id': 456, 'text': 'Van Helsing observed these ominous signs with profound sorrow, watching over her with unceasing vigilance.', 'translation': 'Van Helsing bu meşum işaretleri derin bir kederle gözlemledi ve aralıksız bir teyakkuzla onu korudu.', 'notes': 'unceasing vigilance: aralıksız teyakkuz/uyanıklık.'}, {'id': 457, 'text': "He knew that Dracula was drawing closer, and the vampire's psychic hold over Mina was growing dangerously potent.", 'translation': "Drakula'nın yaklaştığını ve vampirin Mina üzerindeki psişik hakimiyetinin tehlikeli biçimde güçlendiğini biliyordu.", 'notes': 'dangerously potent: tehlikeli derecede güçlü.'}, {'id': 458, 'text': "If they failed to destroy the Count within days, Mina's soul would be lost forever to the darkness.", 'translation': "Eğer Kont'u birkaç gün içinde yok etmeyi başaramazlarsa Mina'nın ruhu sonsuza dek karanlığa karışacaktı.", 'notes': 'lost to darkness: karanlığa karışmış/kaybolmuş.'}, {'id': 459, 'text': "On the fourth of November, Van Helsing's carriage reached the foot of the jagged precipice beneath Castle Dracula.", 'translation': "Dört Kasım'da Van Helsing'in faytonu Drakula Şatosu'nun altındaki sarp uçurumun eteklerine ulaştı.", 'notes': 'foot of precipice: uçurumun etekleri.'}, {'id': 460, 'text': "High above them against the stormy twilight sky loomed the ruined battlements where Harker's nightmare had begun.", 'translation': "Tepelerinde, fırtınalı alacakaranlık gökyüzüne karşı Harker'ın kabusunun başladığı o harap burçlar heybetle yükseliyordu.", 'notes': 'loomed: heybetle yükseliyordu/beliriyordu.'}]}, {'page_no': 24, 'title': 'Purifying the Crypts of Castle Dracula', 'tr_title': "Drakula Şatosu'nun Mahzenlerini Arındırmak", 'vocab_focus': [('sacred circle', 'kutsal çember'), ('sisterhood', 'kardeşlik'), ('sepulchre', 'kabir, lahit'), ('destruction', 'yıkım, yok ediş'), ('consecration', 'kutsama'), ('glacier', 'buzul'), ('hypnotic', 'büyüleyici, hipnotik'), ('sanctuary', 'sığınak, kutsal alan')], 'sentences': [{'id': 461, 'text': 'That evening, a ferocious snowstorm trapped Van Helsing and Mina on the frozen plateau below the castle.', 'translation': "O akşam vahşi bir kar fırtınası Van Helsing ve Mina'yı kalenin altındaki donmuş platoda mahsur bıraktı.", 'notes': 'frozen plateau: donmuş plato.'}, {'id': 462, 'text': 'Van Helsing quickly tethered the shivering horses and built a roaring campfire to stave off the freezing cold.', 'translation': 'Van Helsing titreyen atları hızla bağladı ve dondurucu soğuğu savuşturmak için gürül gürül bir kamp ateşi yaktı.', 'notes': 'stave off cold: soğuğu savuşturmak.'}, {'id': 463, 'text': 'Using crushed consecrated Hosts, the professor drew a wide, sacred circle around Mina upon the snow.', 'translation': "Profesör ezilmiş kutsanmış ekmekleri kullanarak karların üzerine Mina'nın etrafına geniş, kutsal bir çember çizdi.", 'notes': 'sacred circle: kutsal çember.'}, {'id': 464, 'text': '"Stay inside this boundary, Madam Mina; no evil entity can cross this holy barrier," Van Helsing commanded.', 'translation': '"Bu sınırın içinde kalın Madam Mina; hiçbir kötü varlık bu kutsal engeli aşamaz," diye buyurdu Van Helsing.', 'notes': 'evil entity: kötü varlık.'}, {'id': 465, 'text': 'Late that night, through the swirling blizzard, three ethereal female figures materialized in the moonlight.', 'translation': 'O gece geç saatlerde dönen tipinin arasından üç ruhani kadın silueti ay ışığında belirdi.', 'notes': 'ethereal female figures: ruhani kadın siluetleri.'}, {'id': 466, 'text': 'It was the three vampire sisters of Castle Dracula, their ruby lips parted in seductive, mocking smiles.', 'translation': "Yakut dudakları baştan çıkarıcı, alaycı gülümsemelerle aralanmış olanlar Drakula Şatosu'nun üç vampir kardeşiydi.", 'notes': 'mocking smiles: alaycı gülümsemeler.'}, {'id': 467, 'text': '"Come to us, sister!" they whispered in silvery, hypnotic tones; "your place is with us in the shadows!"', 'translation': '"Bize gel kardeşimiz!" diye fısıldadılar gümüşsü, hipnotik tonlarla; "Senin yerin gölgelerde bizim yanımızdır!"', 'notes': 'in the shadows: gölgelerde.'}, {'id': 468, 'text': 'Mina looked toward them with glazed eyes, but the sacred circle prevented her from moving toward the edge.', 'translation': 'Mina donuk gözlerle onlara doğru baktı fakat kutsal çember onun sınıra doğru ilerlemesini engelledi.', 'notes': 'glazed eyes: donuk/camlaşmış gözler.'}, {'id': 469, 'text': 'The vampire women attempted to step across the boundary, but recoiled with shrieks of agony as if burned by fire.', 'translation': 'Vampir kadınlar sınırdan içeri adım atmaya yeltendiler fakat ateşle yanmışçasına acı çığlıklarıyla geri irkildiler.', 'notes': 'step across boundary: sınırı aşmak.'}, {'id': 470, 'text': 'Unable to penetrate the holy circle, the three sisters dissolved into the storm as the first light of dawn broke.', 'translation': 'Kutsal çemberi geçemeyen üç kardeş, şafağın ilk ışıkları sökerken fırtınanın içinde eriyip gittiler.', 'notes': 'first light of dawn broke: şafağın ilk ışıkları söktü.'}, {'id': 471, 'text': 'Leaving Mina sleeping safely within the sacred circle, Van Helsing took his stakes and climbed up to the castle.', 'translation': "Mina'yı kutsal çemberin içinde güvenle uyur halde bırakan Van Helsing kazıklarını alıp kaleye tırmandı.", 'notes': 'sleeping safely: güvenle uyuyan.'}, {'id': 472, 'text': 'He forced his way through the ruined gothic halls, following the sickening stench of decay down into the crypt.', 'translation': 'Midesini bulandıran çürüme kokusunu takip ederek harap gotik salonları aştı ve mahzene indi.', 'notes': 'sickening stench: mide bulandırıcı koku.'}, {'id': 473, 'text': 'In the dark vault, he discovered three stone sepulchres containing the sleeping forms of the three vampire women.', 'translation': 'Karanlık mahzende, üç vampir kadının uyuyan bedenlerini barındıran üç taş lahiti keşfetti.', 'notes': 'stone sepulchres: taş lahitler/kabirler.'}, {'id': 474, 'text': 'Their beauty was breathtaking and voluptuous, their lips glistening with fresh blood, their white fangs bared.', 'translation': 'Güzellikleri nefes kesici ve şehvetliydi; dudakları taze kanla parıldıyor, beyaz dişleri görünüyordu.', 'notes': 'breathtaking beauty: nefes kesici güzellik.'}, {'id': 475, 'text': 'Though his heart trembled with pity, Van Helsing remembered Lucy Westenra and hardened his righteous resolve.', 'translation': "Yüreği acımayla titresene de Van Helsing Lucy Westenra'yı hatırladı ve haklı kararlılığını perçinledi.", 'notes': 'righteous resolve: haklı kararlılık.'}, {'id': 476, 'text': 'With solemn prayers on his lips, he drove wooden stakes through their hearts, one by one, with his heavy mallet.', 'translation': 'Dudaklarında vakur dualarla, ağır tokmağıyla tahta kazıkları teker teker kalplerine sapladı.', 'notes': 'solemn prayers: vakur dualar.'}, {'id': 477, 'text': 'The creatures shrieked and writhed in terrible death throes before disintegrating into heaps of dry, grey dust.', 'translation': 'Yaratıklar kuru gri toz yığınlarına dönüşmeden önce korkunç can çekişmelerle çığlık atıp kıvrandılar.', 'notes': 'death throes: can çekişme nöbetleri.'}, {'id': 478, 'text': 'Van Helsing severed their heads and placed garlic and holy wafers within each empty stone coffin.', 'translation': 'Van Helsing başlarını kesti ve her boş taş tabutun içine sarımsak ve kutsanmış ekmek yerleştirdi.', 'notes': 'empty stone coffin: boş taş tabut.'}, {'id': 479, 'text': "Finally, he entered Count Dracula's colossal tomb, sanctifying the stone sarcophagus with portions of the Host.", 'translation': "Son olarak Kont Drakula'nın devasa kabrine girdi; taş lahiti kutsanmış ekmek parçalarıyla arındırdı.", 'notes': 'stone sarcophagus: taş lahit.'}, {'id': 480, 'text': 'Castle Dracula was spiritually cleansed forever; the King of Vampires would find no sanctuary within its walls!', 'translation': 'Drakula Şatosu sonsuza dek ruhani olarak temizlendi; Vampirler Kralı duvarları arasında artık hiçbir sığınak bulamayacaktı!', 'notes': 'spiritually cleansed: ruhani olarak arındırılmış.'}]}, {'page_no': 25, 'title': 'The Sunset Battle on the Borgo Pass', 'tr_title': "Borgo Geçidi'nde Günbatımı Savaşı ve Drakula'nın Sonu", 'vocab_focus': [('kukri', 'gurka kaması, kavisli bıçak'), ('bowie knife', 'avcı bıçağı'), ('sunset', 'günbatımı'), ('convoy', 'konvoy, kervan'), ('dissolution', 'erime, yok olma'), ('sacrifice', 'fedakarlık, kurban'), ('deliverance', 'kurtuluş'), ('legacy', 'miras')], 'sentences': [{'id': 481, 'text': 'Van Helsing scrambled down the mountain path and rejoined Mina as the afternoon sun began to sink.', 'translation': "Van Helsing dağ patikasından aşağı indi ve öğleden sonra güneşi batmaya başlarken Mina'nın yanına döndü.", 'notes': 'began to sink: batmaya başladı.'}, {'id': 482, 'text': 'Looking through binoculars across the snowy pass, Van Helsing spotted a fast-moving convoy of horsemen approaching.', 'translation': 'Karlı geçidi dürbünle tarayan Van Helsing, hızla yaklaşan atlı bir konvoy fark etti.', 'notes': 'fast-moving convoy: hızlı ilerleyen konvoy.'}, {'id': 483, 'text': 'A heavy wooden wagon drawn by eight galloping horses was surrounded by a dozen armed Slovak gypsies.', 'translation': 'Dört nala koşan sekiz atın çektiği ağır tahta vagon, bir düzine silahlı Slovak çingene tarafından çevrelenmişti.', 'notes': 'galloping horses: dört nala koşan atlar.'}, {'id': 484, 'text': 'Upon the wagon bed lay the final rectangular wooden box containing the sleeping body of Count Dracula!', 'translation': "Vagonun kasasında Kont Drakula'nın uyuyan bedenini taşıyan o son dikdörtgen ahşap sandık duruyordu!", 'notes': 'wagon bed: vagon kasası.'}, {'id': 485, 'text': 'Suddenly, from the valley below, two pairs of galloping riders charged furiously toward the moving wagon.', 'translation': 'Ansızın, aşağıdaki vadiden gelen iki çift atlı hareket eden vagona doğru öfkeyle hücum etti.', 'notes': 'charged furiously: öfkeyle hücum etti.'}, {'id': 486, 'text': 'Jonathan Harker and Arthur Holmwood attacked from the left, while Dr. Seward and Quincey Morris charged from the right.', 'translation': 'Jonathan Harker ve Arthur Holmwood soldan saldırırken Doktor Seward ve Quincey Morris sağdan yüklendi.', 'notes': 'attacked from the left: soldan saldırdı.'}, {'id': 487, 'text': 'The gypsies drew their rifles and long hunting knives, forming a defensive ring around the speeding wagon.', 'translation': 'Çingeneler hızla giden vagonun etrafında bir savunma çemberi oluşturarak tüfeklerini ve uzun av bıçaklarını çektiler.', 'notes': 'defensive ring: savunma çemberi.'}, {'id': 488, 'text': 'Gunfire echoed across the snowy cliffs as Quincey Morris leaped from his saddle and charged the defenders.', 'translation': 'Quincey Morris eyerinden atlayıp savunucuların üzerine hücum ederken karlı kayalıklarda silah sesleri yankılandı.', 'notes': 'gunfire echoed: silah sesleri yankılandı.'}, {'id': 489, 'text': "A fierce gypsy drove a long dagger deep into Quincey's side, but the brave Texan fought on without flinching.", 'translation': "Azılı bir çingene uzun bir hançeri Quincey'nin böğrüne sapladı fakat cesur Teksaslı geri adım atmadan dövüşmeye devam etti.", 'notes': 'without flinching: geri adım atmadan/çekinmeden.'}, {'id': 490, 'text': 'Jonathan Harker sprang onto the wagon bed like a mountain lion, wielding his gleaming kukri blade with both hands.', 'translation': 'Jonathan Harker bir dağ aslanı gibi vagon kasasına sıçradı; iki eliyle parıldayan kavisli kamasını savurdu.', 'notes': 'like a mountain lion: dağ aslanı gibi.'}, {'id': 491, 'text': 'The sun was touching the jagged mountain peaks, casting long, fiery red shadows across the bloodstained snow.', 'translation': 'Güneş sarp dağ zirvelerine değmek üzereydi; kana bulanmış karın üzerine uzun, alev kırmızısı gölgeler düşürüyordu.', 'notes': 'bloodstained snow: kana bulanmış kar.'}, {'id': 492, 'text': 'In just a few fleeting seconds, darkness would fall and the Count would awaken with unstoppable supernatural fury!', 'translation': 'Birkaç saniye içinde karanlık çökecek ve Kont durdurulamaz bir doğaüstü gazapla uyanacaktı!', 'notes': 'unstoppable fury: durdurulamaz gazap/öfke.'}, {'id': 493, 'text': 'With a mighty heave of his shoulders, Harker pried off the heavy wooden lid of the coffin-like box.', 'translation': 'Omuzlarının muazzam bir hamlesiyle Harker tabutumsu sandığın ağır ahşap kapağını kanırtarak açtı.', 'notes': 'pried off the lid: kapağı kanırtarak açtı.'}, {'id': 494, 'text': 'Inside lay Count Dracula, his eyes snapping open with a terrifying glare of hatred and impending triumph!', 'translation': 'İçeride Kont Drakula yatıyordu; gözleri nefretin ve yaklaşan zaferin korkunç bir parıltısıyla aniden açıldı!', 'notes': 'impending triumph: yaklaşan zafer.'}, {'id': 495, 'text': "Before the monster could rise, Jonathan's kukri slashed through his throat in a sweeping, decapitating arc!", 'translation': "Canavar ayağa kalkamadan Jonathan'ın kaması geniş bir boyun kesme kavisiyle onun boğazını yardı!", 'notes': 'slashed through throat: boğazını kesti.'}, {'id': 496, 'text': "At the exact same fraction of a second, the dying Quincey Morris lunged forward and plunged his bowie knife into Dracula's heart!", 'translation': "Tam aynı saniyenin kesrinde, ölmekte olan Quincey Morris ileri atıldı ve avcı bıçağını Drakula'nın kalbine sapladı!", 'notes': 'plunged knife into heart: bıçağı kalbine sapladı.'}, {'id': 497, 'text': 'The vampire uttered a sigh of profound peace; in an instant, his entire body dissolved into a shower of sparkling dust!', 'translation': 'Vampir derin bir huzur iç çekişi koyverdi; bir anda tüm bedeni ışıltılı bir toz yağmuruna dönüşerek eridi!', 'notes': 'sparkling dust: parıldayan toz.'}, {'id': 498, 'text': 'The gypsy wagon was empty, the surviving guards fled in terror, and the wind scattered the dust across the Carpathians.', 'translation': 'Çingene vagonu boş kaldı, sağ kalan muhafızlar dehşetle kaçtı ve rüzgar tozu Karpatların üzerine savurdu.', 'notes': 'scattered the dust: tozu savurdu.'}, {'id': 499, 'text': "At that glorious moment, the red scar upon Mina's forehead vanished completely, restoring her skin to pristine purity!", 'translation': "O muhteşem anda, Mina'nın alnındaki kırmızı yara izi tamamen silindi ve teni ilk günkü kusursuz saflığına kavuştu!", 'notes': 'pristine purity: ilk günkü saflık/lekesizlik.'}, {'id': 500, 'text': 'Quincey Morris looked up at Mina with a joyful, dying smile—"I am glad to have died for her; the curse is broken!"—and closed his eyes in peace forever.', 'translation': 'Quincey Morris can verirken sevinç dolu bir tebessümle Mina\'ya baktı—"Onun uğruna öldüğüme memnunum; lanet kırıldı!"—ve gözlerini ebedi bir huzurla sonsuza dek kapadı.', 'notes': 'the curse is broken: lanet bozuldu/kırıldı.'}]}]
